(window.MNEMO_GRAMMAR = window.MNEMO_GRAMMAR || {}).de = [{"id":"de-a0-pronomen","lv":"A0","e":"👤","t":"Личные местоимения: ich, du, er, sie… и вежливое Sie","x":"Личные местоимения — первое, что нужно знать, чтобы строить предложения. В немецком предложении подлежащее почти всегда обязательно: нельзя просто сказать «Живу в Берлине», нужно **Ich wohne in Berlin**.\n\n| Лицо | Единственное число | Множественное число |\n| 1-е | ich — я | wir — мы |\n| 2-е | du — ты | ihr — вы (несколько человек, на «ты») |\n| 3-е | er / sie / es — он / она / оно | sie — они |\n| Вежливая форма | Sie — Вы | Sie — Вы |\n\n**Sie** с большой буквы — вежливое обращение к одному или нескольким людям: **Kommen Sie aus Berlin?** — Вы из Берлина? Глагол при этом стоит в той же форме, что и при **sie** (они).\n\n**du** — к другу, ребёнку, родственнику. **ihr** — к группе людей, с каждым из которых вы на «ты»: **Wo wohnt ihr?** — Где вы живёте?\n\n**er / sie / es** заменяют не только людей, но и предметы — по грамматическому роду слова: **der Tisch → er**, **die Lampe → sie**, **das Kind → es**.\n\n- **Ich** пишется с маленькой буквы (кроме начала предложения).\n- **sie** может значить «она» или «они» — смотрите на форму глагола: **sie wohnt** (она), **sie wohnen** (они).\n\n**Типичные ошибки русскоговорящих:**\n- Путают **ihr** и **Sie**: русское «вы» бывает и дружеским, и вежливым. Коллективное «вы» друзьям — **ihr**, вежливое «Вы» — **Sie**.\n- Пропускают местоимение, как в русском: ✗ Komme aus Moskau → **Ich komme aus Moskau**.\n- Пишут **Ich** с большой буквы в середине предложения или **sie** (Вы) с маленькой.","q":[{"k":"mc","s":"___ heiße Anna.","o":["Ich","Du","Er"],"a":0,"ru":"Меня зовут Анна."},{"k":"mc","s":"Das ist Peter. ___ kommt aus Wien.","o":["Sie","Er","Es"],"a":1,"ru":"Это Петер. Он из Вены."},{"k":"mc","s":"Herr Müller, kommen ___ aus Berlin?","o":["du","ihr","Sie"],"a":2,"ru":"Господин Мюллер, Вы из Берлина?"},{"k":"mc","s":"Paul und Lisa sind Freunde. ___ wohnen in Köln.","o":["Er","Wir","Ihr","Sie"],"a":3,"ru":"Пауль и Лиза — друзья. Они живут в Кёльне."},{"k":"type","s":"___ (ты) bist mein Freund.","a":["Du"],"ru":"Ты мой друг."},{"k":"type","s":"Anna, Tom, wo wohnt ___ (вы — друзьям)?","a":["ihr"],"ru":"Анна, Том, где вы живёте?"},{"k":"type","s":"Das ist Maria. ___ (она) ist nett.","a":["Sie"],"ru":"Это Мария. Она милая."},{"k":"type","s":"Das Kind spielt. ___ (оно) ist klein.","a":["Es"],"ru":"Ребёнок играет. Он маленький."},{"k":"order","w":["heißt","du","wie"],"a":["Wie heißt du"],"ru":"Как тебя зовут?"},{"k":"order","w":["wir","in","wohnen","Berlin"],"a":["Wir wohnen in Berlin","In Berlin wohnen wir"],"ru":"Мы живём в Берлине."},{"k":"tr","ru":"Он из Москвы.","a":["Er kommt aus Moskau","Er ist aus Moskau"]},{"k":"tr","ru":"Вы из Германии? (вежливо)","a":["Kommen Sie aus Deutschland","Sind Sie aus Deutschland"]}]},{"id":"de-a0-sein","lv":"A0","e":"🟰","t":"Глагол sein — «быть»","x":"В русском языке в настоящем времени мы говорим «Я студент», без глагола. В немецком глагол-связка обязателен: **Ich bin Student.** Это глагол **sein** (быть). Он неправильный — формы нужно выучить наизусть.\n\n| Лицо | sein | Пример |\n| ich | bin | Ich bin Anna. — Я Анна. |\n| du | bist | Du bist nett. — Ты милый. |\n| er / sie / es | ist | Er ist Arzt. — Он врач. |\n| wir | sind | Wir sind aus Russland. — Мы из России. |\n| ihr | seid | Ihr seid müde. — Вы устали. |\n| sie / Sie | sind | Sind Sie Lehrer? — Вы учитель? |\n\n**Когда используется sein:**\n- имя: **Ich bin Olga.**\n- происхождение: **Wir sind aus Kasan.**\n- профессия (без артикля!): **Sie ist Lehrerin.** — Она учительница.\n- описание: **Das Haus ist groß.** — Дом большой.\n- место: **Peter ist zu Hause.** — Петер дома.\n\nВ вопросе без вопросительного слова **sein** стоит на первом месте: **Bist du Student?** — Ты студент?\n\n**Типичные ошибки русскоговорящих:**\n- Пропускают глагол: ✗ Ich Student → **Ich bin Student**; ✗ Das Wetter gut → **Das Wetter ist gut**.\n- Ставят артикль перед профессией: ✗ Ich bin ein Arzt → **Ich bin Arzt**.\n- Путают **seid** (вы есть) и **seit** (с, начиная с) — звучат одинаково, пишутся по-разному.\n- Говорят ✗ du bin или ✗ er sind — каждое лицо имеет свою форму.","q":[{"k":"mc","s":"Ich ___ Student.","o":["bin","bist","ist"],"a":0,"ru":"Я студент."},{"k":"mc","s":"Wir ___ aus Russland.","o":["seid","sind","ist","bin"],"a":1,"ru":"Мы из России."},{"k":"mc","s":"Ihr ___ sehr nett.","o":["sind","ist","seid"],"a":2,"ru":"Вы (ребята) очень милые."},{"k":"mc","s":"Das Wetter ___ heute gut.","o":["sind","bist","bin","ist"],"a":3,"ru":"Погода сегодня хорошая."},{"k":"type","s":"Du ___ (sein) müde.","a":["bist"],"ru":"Ты устал."},{"k":"type","s":"Frau Schmidt, ___ (sein) Sie Lehrerin?","a":["sind"],"ru":"Госпожа Шмидт, Вы учительница?"},{"k":"type","s":"Er ___ (sein) Arzt.","a":["ist"],"ru":"Он врач."},{"k":"type","s":"Anna und Tom ___ (sein) in Berlin.","a":["sind"],"ru":"Анна и Том в Берлине."},{"k":"order","w":["ist","das","Haus","groß"],"a":["Das Haus ist groß","Groß ist das Haus"],"ru":"Дом большой."},{"k":"order","w":["bist","du","Lehrer"],"a":["Bist du Lehrer"],"ru":"Ты учитель?"},{"k":"tr","ru":"Я из России.","a":["Ich bin aus Russland","Ich komme aus Russland"]},{"k":"tr","ru":"Вы (ребята) дома?","a":["Seid ihr zu Hause","Seid ihr daheim"]}]},{"id":"de-a0-erste-verben","lv":"A0","e":"👋","t":"Первые глаголы: heißen, kommen, wohnen","x":"С этих трёх глаголов начинается любое знакомство: **Wie heißt du? Woher kommst du? Wo wohnst du?** — Как тебя зовут? Откуда ты? Где ты живёшь?\n\nНемецкий глагол меняет окончание в зависимости от лица. Отбрасываем от инфинитива **-en** и получаем основу: **komm-en → komm-**. К основе добавляем окончание.\n\n| Лицо | heißen | kommen | wohnen |\n| ich | heiße | komme | wohne |\n| du | heißt | kommst | wohnst |\n| er / sie / es | heißt | kommt | wohnt |\n| wir | heißen | kommen | wohnen |\n| ihr | heißt | kommt | wohnt |\n| sie / Sie | heißen | kommen | wohnen |\n\nЗапомните окончания: **ich -e, du -st, er -t, wir -en, ihr -t, sie/Sie -en**.\n\nОсобенность **heißen**: основа уже кончается на **ß**, поэтому у **du** добавляется только **-t**: **du heißt** (не ✗ heißst).\n\n**Полезные конструкции:**\n- **Ich heiße Olga.** — Меня зовут Ольга. (дословно: «Я называюсь Ольга»)\n- **Ich komme aus Russland.** — Я из России. Для происхождения — **aus**.\n- **Ich wohne in Moskau.** — Я живу в Москве. Для места — **in**.\n\n**Типичные ошибки русскоговорящих:**\n- Переводят «меня зовут» дословно: ✗ Mich ruft man Olga → **Ich heiße Olga**.\n- Путают предлоги: ✗ Ich komme in Russland → **Ich komme aus Russland**; ✗ Ich wohne aus Moskau → **Ich wohne in Moskau**.\n- Пишут ✗ du heißst или забывают окончание: ✗ ich wohn → **ich wohne**.","q":[{"k":"mc","s":"Wie ___ du?","o":["heißt","heiße","heißen"],"a":0,"ru":"Как тебя зовут?"},{"k":"mc","s":"Ich ___ aus Polen.","o":["kommst","komme","kommt"],"a":1,"ru":"Я из Польши."},{"k":"mc","s":"Wo ___ Sie?","o":["wohnst","wohnt","wohnen"],"a":2,"ru":"Где Вы живёте?"},{"k":"mc","s":"Maria ___ in Wien.","o":["wohne","wohnen","wohnst","wohnt"],"a":3,"ru":"Мария живёт в Вене."},{"k":"type","s":"Ich ___ (heißen) Olga.","a":["heiße"],"ru":"Меня зовут Ольга."},{"k":"type","s":"Woher ___ (kommen) du?","a":["kommst"],"ru":"Откуда ты?"},{"k":"type","s":"Er ___ (wohnen) in München.","a":["wohnt"],"ru":"Он живёт в Мюнхене."},{"k":"type","s":"Wie ___ (heißen) Sie?","a":["heißen"],"ru":"Как Вас зовут?"},{"k":"order","w":["kommst","woher","du"],"a":["Woher kommst du"],"ru":"Откуда ты?"},{"k":"order","w":["wohne","ich","Hamburg","in"],"a":["Ich wohne in Hamburg","In Hamburg wohne ich"],"ru":"Я живу в Гамбурге."},{"k":"tr","ru":"Меня зовут Иван.","a":["Ich heiße Iwan","Ich heiße Ivan","Mein Name ist Iwan","Mein Name ist Ivan"]},{"k":"tr","ru":"Где ты живёшь?","a":["Wo wohnst du","Wo lebst du"]}]},{"id":"de-a0-fragen","lv":"A0","e":"❓","t":"Вопросы: W-Fragen и вопросы «да/нет»","x":"В немецком два основных типа вопросов, и в обоих важен порядок слов.\n\n**1. Вопрос с вопросительным словом (W-Frage).** Вопросительное слово на первом месте, глагол — на втором, затем подлежащее:\n- **Wo wohnst du?** — Где ты живёшь?\n- **Was ist das?** — Что это?\n\n| Слово | Значение | Пример |\n| wer | кто | Wer ist das? |\n| was | что | Was machst du? |\n| wo | где | Wo ist Anna? |\n| woher | откуда | Woher kommen Sie? |\n| wie | как | Wie heißt du? |\n| wie alt | сколько лет | Wie alt bist du? |\n| wann | когда | Wann kommst du? |\n\n**2. Вопрос «да/нет» (Ja/Nein-Frage).** Вопросительного слова нет, глагол стоит на **первом** месте:\n- **Kommst du aus Italien?** — Ты из Италии? — **Ja.** / **Nein, aus Spanien.**\n- **Ist das dein Buch?** — Это твоя книга?\n\nИнтонация в вопросе «да/нет» идёт вверх, в W-вопросе — обычно вниз.\n\n**Типичные ошибки русскоговорящих:**\n- Сохраняют русский порядок: ✗ Wo du wohnst? → **Wo wohnst du?**; ✗ Du kommst aus Italien? (только с удивлением) → **Kommst du aus Italien?**\n- Путают **wer** (кто) и **wo** (где) — они звучат похоже на русское «во» и «вер». Запомните: **wer = кто, wo = где**.\n- Спрашивают о возрасте через «сколько»: ✗ Wie viel Jahre hast du? → **Wie alt bist du?**","q":[{"k":"mc","s":"___ ist das? – Das ist mein Bruder.","o":["Wer","Was","Wo"],"a":0,"ru":"Кто это? – Это мой брат."},{"k":"mc","s":"___ wohnst du? – In Köln.","o":["Wer","Wo","Was"],"a":1,"ru":"Где ты живёшь? – В Кёльне."},{"k":"mc","s":"___ alt bist du? – 20.","o":["Was","Wo","Wie"],"a":2,"ru":"Сколько тебе лет? – 20."},{"k":"mc","s":"___ kommen Sie? – Aus Spanien.","o":["Wo","Wie","Wer","Woher"],"a":3,"ru":"Откуда Вы? – Из Испании."},{"k":"type","s":"___ (что) ist das? – Ein Buch.","a":["Was"],"ru":"Что это? – Книга."},{"k":"type","s":"___ (когда) kommst du? – Morgen.","a":["Wann"],"ru":"Когда ты придёшь? – Завтра."},{"k":"type","s":"___ (как) heißt du?","a":["Wie"],"ru":"Как тебя зовут?"},{"k":"type","s":"___ (kommen) du aus Italien? – Nein, aus Spanien.","a":["Kommst"],"ru":"Ты из Италии? – Нет, из Испании."},{"k":"order","w":["du","Deutsch","lernst"],"a":["Lernst du Deutsch"],"ru":"Ты учишь немецкий?"},{"k":"order","w":["wohnt","wo","Anna"],"a":["Wo wohnt Anna"],"ru":"Где живёт Анна?"},{"k":"tr","ru":"Кто это?","a":["Wer ist das"]},{"k":"tr","ru":"Откуда Вы?","a":["Woher kommen Sie","Woher sind Sie"]}]},{"id":"de-a1-artikel","lv":"A1","e":"📘","t":"Артикли der, die, das и род существительных","x":"Каждое немецкое существительное имеет род: мужской (**der**), женский (**die**) или средний (**das**). Существительные всегда пишутся с большой буквы. Род часто не совпадает с русским, поэтому слово нужно учить **вместе с артиклем**: не «Tisch», а **der Tisch**.\n\n| der (м. р.) | die (ж. р.) | das (ср. р.) |\n| der Tisch — стол | die Lampe — лампа | das Buch — книга |\n| der Mann — мужчина | die Frau — женщина | das Kind — ребёнок |\n| der Mond — луна | die Sonne — солнце | das Mädchen — девочка |\n\n**Подсказки по окончаниям:**\n- **der**: люди мужского пола (**der Lehrer**), дни недели, месяцы, времена года (**der Montag, der Mai, der Sommer**), слова на **-ling, -ismus**.\n- **die**: большинство слов на **-e** (**die Tasche**), а также на **-ung, -heit, -keit, -schaft, -ion, -tät** (**die Zeitung, die Freiheit, die Information**).\n- **das**: уменьшительные на **-chen, -lein** (**das Brötchen**), большинство слов на **-um, -ment** (**das Museum, das Dokument**), инфинитивы (**das Essen**).\n\nАртикль определяет и местоимение: **Der Tisch ist neu. Er ist schön.** — Стол новый. Он красивый. **Die Wohnung ist groß. Sie ist hell.**\n\n**Типичные ошибки русскоговорящих:**\n- Переносят русский род: ✗ der Sonne (как «солнце» — ср. р.) → **die Sonne**; ✗ die Mond → **der Mond**.\n- **das Mädchen** — средний род из-за **-chen**, хотя это девочка; местоимение тоже часто **es**.\n- Учат слова без артикля, а потом угадывают. Учите сразу: **die Zeitung, das Auto, der Stuhl**.","q":[{"k":"mc","s":"___ Zeitung ist alt.","o":["Der","Die","Das"],"a":1,"ru":"Газета старая."},{"k":"mc","s":"___ Mädchen heißt Lena.","o":["Der","Die","Das"],"a":2,"ru":"Девочку зовут Лена."},{"k":"mc","s":"___ Tisch ist neu.","o":["Der","Die","Das"],"a":0,"ru":"Стол новый."},{"k":"mc","s":"___ Brötchen ist frisch.","o":["Das","Die","Der"],"a":0,"ru":"Булочка свежая."},{"k":"type","s":"Das ist ___ (der/die/das) Lampe. Sie ist neu.","a":["die"],"ru":"Это лампа. Она новая."},{"k":"type","s":"Wo ist ___ (der/die/das) Auto?","a":["das"],"ru":"Где машина?"},{"k":"type","s":"___ (der/die/das) Lehrer kommt aus Bonn.","a":["Der"],"ru":"Учитель из Бонна."},{"k":"type","s":"Wie ist ___ (der/die/das) Wetter?","a":["das"],"ru":"Какая погода?"},{"k":"order","w":["Stuhl","der","ist","bequem"],"a":["Der Stuhl ist bequem","Bequem ist der Stuhl"],"ru":"Стул удобный."},{"k":"order","w":["die","teuer","Tasche","ist"],"a":["Die Tasche ist teuer","Teuer ist die Tasche"],"ru":"Сумка дорогая."},{"k":"tr","ru":"Солнце светит.","a":["Die Sonne scheint"]},{"k":"tr","ru":"Машина новая.","a":["Das Auto ist neu","Der Wagen ist neu"]}]},{"id":"de-a1-praesens","lv":"A1","e":"🔤","t":"Настоящее время (Präsens): спряжение глаголов и haben","x":"Präsens — настоящее время. Оно же часто выражает будущее: **Morgen fahre ich nach Berlin.** — Завтра я еду в Берлин.\n\n**Правильные глаголы:** основа + окончание.\n\n| Лицо | machen | arbeiten | haben |\n| ich | mache | arbeite | habe |\n| du | machst | arbeitest | hast |\n| er / sie / es | macht | arbeitet | hat |\n| wir | machen | arbeiten | haben |\n| ihr | macht | arbeitet | habt |\n| sie / Sie | machen | arbeiten | haben |\n\n**Особые случаи:**\n- Основа на **-t, -d**: вставляется **-e-**: **du arbeitest, er findet**.\n- Основа на **-s, -ß, -z**: у **du** только **-t**: **du tanzt, du heißt**.\n- **Глаголы со сменой гласной** (только у **du** и **er/sie/es**):\n- **a → ä**: fahren → **du fährst, er fährt**; schlafen → **er schläft**\n- **e → i**: sprechen → **er spricht**; essen → **er isst**; nehmen → **er nimmt**\n- **e → ie**: lesen → **er liest**; sehen → **er sieht**\n\nУ **wir, ihr, sie** гласная не меняется: **wir fahren, ihr lest**.\n\n**haben** — неправильный глагол (**du hast, er hat**). «У меня есть» по-немецки — **Ich habe**: **Ich habe einen Bruder.**\n\n**Типичные ошибки русскоговорящих:**\n- ✗ du arbeitst → **du arbeitest**; ✗ er arbeitt → **er arbeitet**.\n- Забывают смену гласной: ✗ er fahrt, er lest → **er fährt, er liest**; или меняют её у **ihr**: ✗ ihr fährt → **ihr fahrt**.\n- Переводят «у меня есть» дословно: ✗ Bei mir ist ein Bruder → **Ich habe einen Bruder**.","q":[{"k":"mc","s":"Wir ___ jeden Tag.","o":["arbeiten","arbeitet","arbeitest"],"a":0,"ru":"Мы работаем каждый день."},{"k":"mc","s":"Du ___ sehr gut Deutsch.","o":["sprechst","sprichst","spricht"],"a":1,"ru":"Ты очень хорошо говоришь по-немецки."},{"k":"mc","s":"Er ___ einen Bruder.","o":["habt","hast","hat"],"a":2,"ru":"У него есть брат."},{"k":"mc","s":"Ihr ___ gern Musik.","o":["höre","hören","hörst","hört"],"a":3,"ru":"Вы (ребята) любите слушать музыку."},{"k":"type","s":"Du ___ (arbeiten) viel.","a":["arbeitest"],"ru":"Ты много работаешь."},{"k":"type","s":"Mein Vater ___ (fahren) nach Berlin.","a":["fährt"],"ru":"Мой отец едет в Берлин."},{"k":"type","s":"Ich ___ (haben) heute Zeit.","a":["habe"],"ru":"У меня сегодня есть время."},{"k":"type","s":"Lisa ___ (lesen) ein Buch.","a":["liest"],"ru":"Лиза читает книгу."},{"k":"order","w":["isst","Anna","gern","Pizza"],"a":["Anna isst gern Pizza","Pizza isst Anna gern","Gern isst Anna Pizza"],"ru":"Анна любит есть пиццу."},{"k":"order","w":["ihr","heute","was","macht"],"a":["Was macht ihr heute"],"ru":"Что вы (ребята) делаете сегодня?"},{"k":"tr","ru":"Ты хорошо танцуешь.","a":["Du tanzt gut"]},{"k":"tr","ru":"Она видит Тома.","a":["Sie sieht Tom"]}]},{"id":"de-a1-wortstellung","lv":"A1","e":"🧩","t":"Порядок слов: глагол на втором месте","x":"Главное правило немецкого повествовательного предложения: **спрягаемый глагол стоит на втором месте**. На первом месте может стоять подлежащее, время, место или дополнение — но тогда подлежащее «переходит» за глагол (**инверсия**).\n\n| 1-е место | 2-е место (глагол) | дальше |\n| Ich | lerne | heute Deutsch. |\n| Heute | lerne | ich Deutsch. |\n| Deutsch | lerne | ich heute. |\n| Am Abend | kochen | wir. |\n\nПервое место — это не одно слово, а один член предложения: **Am Wochenende** (два слова) — одна позиция.\n\n**Вопросы:**\n- W-вопрос: глагол на втором месте — **Was machst du?**\n- Вопрос «да/нет»: глагол на первом месте — **Machst du Pause?**\n\n**Союзы und, aber, oder, denn** стоят на «нулевой» позиции и не меняют порядок: **Ich bin müde, aber ich arbeite noch.** — Я устал, но ещё работаю. **Ich lerne Deutsch, denn ich wohne in Wien.**\n\n**Типичные ошибки русскоговорящих:**\n- Русский порядок после обстоятельства: ✗ Heute ich gehe ins Kino → **Heute gehe ich ins Kino**; ✗ Morgen mein Bruder fährt… → **Morgen fährt mein Bruder…**\n- Делают инверсию после **aber, und, denn**: ✗ …, aber arbeite ich noch → **…, aber ich arbeite noch**. Эти союзы не занимают позицию.\n- Думают, что порядок свободный, как в русском. Положение глагола в немецком фиксировано — свободно только то, что стоит на первом месте.","q":[{"k":"mc","s":"Heute ___ ins Kino.","o":["ich gehe","gehe ich","gehen ich"],"a":1,"ru":"Сегодня я иду в кино."},{"k":"mc","s":"Ich lerne Deutsch, ___ ich arbeite in Wien.","o":["weil","dass","und"],"a":2,"ru":"Я учу немецкий и работаю в Вене."},{"k":"mc","s":"Am Wochenende ___ gern Fußball.","o":["spielt mein Bruder","mein Bruder spielt","spielen mein Bruder"],"a":0,"ru":"По выходным мой брат любит играть в футбол."},{"k":"mc","s":"Kommst du heute? – Nein, heute ___ keine Zeit.","o":["ich habe","hast du","haben ich","habe ich"],"a":3,"ru":"Ты придёшь сегодня? – Нет, сегодня у меня нет времени."},{"k":"type","s":"Morgen ___ (fahren) wir nach Hamburg.","a":["fahren"],"ru":"Завтра мы едем в Гамбург."},{"k":"type","s":"Im Sommer fliege ___ (я) nach Spanien.","a":["ich"],"ru":"Летом я лечу в Испанию."},{"k":"type","s":"Ich bin müde, aber ich ___ (arbeiten) noch.","a":["arbeite"],"ru":"Я устал, но ещё работаю."},{"k":"type","s":"Jetzt ___ (machen) Tom Pause.","a":["macht"],"ru":"Сейчас Том делает перерыв."},{"k":"order","w":["Deutsch","lerne","heute","ich"],"a":["Heute lerne ich Deutsch","Ich lerne heute Deutsch","Deutsch lerne ich heute"],"ru":"Сегодня я учу немецкий."},{"k":"order","w":["wir","Abend","am","kochen"],"a":["Am Abend kochen wir","Wir kochen am Abend"],"ru":"Вечером мы готовим."},{"k":"tr","ru":"Сегодня я работаю дома.","a":["Heute arbeite ich zu Hause","Ich arbeite heute zu Hause","Heute arbeite ich daheim","Ich arbeite heute daheim","Zu Hause arbeite ich heute"]},{"k":"tr","ru":"Завтра мой брат едет в Мюнхен.","a":["Morgen fährt mein Bruder nach München","Mein Bruder fährt morgen nach München"]}]},{"id":"de-a1-ein-kein-nicht","lv":"A1","e":"🚫","t":"Неопределённый артикль ein/eine и отрицание kein/nicht","x":"**Неопределённый артикль** употребляется, когда предмет упоминается впервые или «какой-то, один из»: **Das ist ein Hund. Der Hund heißt Bello.**\n\n| | м. р. | ж. р. | ср. р. | мн. ч. |\n| неопределённый | ein Tisch | eine Lampe | ein Buch | — Bücher |\n| отрицание | kein Tisch | keine Lampe | kein Buch | keine Bücher |\n\nВо множественном числе неопределённого артикля нет: **Das sind Äpfel.** — Это яблоки.\n\n**kein / keine** — отрицание существительного. Используется вместо **ein** и там, где артикля нет:\n- **Das ist kein Hund, das ist eine Katze.** — Это не собака, это кошка.\n- **Ich habe keine Zeit.** — У меня нет времени.\n- **Wir haben keine Kinder.** — У нас нет детей.\n\n**nicht** — отрицание всего остального: глагола, прилагательного, наречия, имени или существительного с определённым артиклем:\n- **Ich komme nicht.** — Я не приду.\n- **Das Essen ist nicht gut.** — Еда невкусная.\n- **Ich wohne nicht in Berlin.**\n- **Das ist nicht der Bus nach Bonn.**\n\n**nicht** обычно стоит в конце предложения или перед тем словом, которое отрицается: **Peter kommt heute nicht.**\n\n**Типичные ошибки русскоговорящих:**\n- Переводят «не» всегда как **nicht**: ✗ Ich habe nicht Zeit, ✗ Das ist nicht ein Problem → **Ich habe keine Zeit**, **Das ist kein Problem**.\n- Ставят **ein** во множественном числе: ✗ eine Bücher → **Bücher**.\n- Путают **nein** (нет — ответ) и **nicht/kein**.","q":[{"k":"mc","s":"Das ist ___ Apfel.","o":["ein","eine","einen"],"a":0,"ru":"Это яблоко."},{"k":"mc","s":"Das ist kein Hund, das ist ___ Katze.","o":["ein","eine","kein"],"a":1,"ru":"Это не собака, это кошка."},{"k":"mc","s":"Ich habe heute ___ Zeit.","o":["nicht","kein","keine"],"a":2,"ru":"У меня сегодня нет времени."},{"k":"mc","s":"Das Essen ist ___ gut.","o":["kein","keine","nein","nicht"],"a":3,"ru":"Еда невкусная."},{"k":"type","s":"Ist das ein Fahrrad? – Nein, das ist ___ (отрицание) Fahrrad.","a":["kein"],"ru":"Это велосипед? – Нет, это не велосипед."},{"k":"type","s":"Ich wohne ___ (отрицание) in Berlin.","a":["nicht"],"ru":"Я не живу в Берлине."},{"k":"type","s":"Hier ist ___ (неопределённый артикль) Bank.","a":["eine"],"ru":"Здесь есть банк."},{"k":"type","s":"Wir haben ___ (отрицание) Kinder.","a":["keine"],"ru":"У нас нет детей."},{"k":"order","w":["kein","das","Problem","ist"],"a":["Das ist kein Problem"],"ru":"Это не проблема."},{"k":"order","w":["nicht","Peter","heute","kommt"],"a":["Peter kommt heute nicht","Heute kommt Peter nicht"],"ru":"Петер сегодня не придёт."},{"k":"tr","ru":"У меня нет машины.","a":["Ich habe kein Auto","Ich habe keinen Wagen"]},{"k":"tr","ru":"Кофе не горячий.","a":["Der Kaffee ist nicht heiß"]}]},{"id":"de-a1-plural","lv":"A1","e":"🔢","t":"Множественное число существительных","x":"Во множественном числе у всех существительных один артикль — **die**: **der Tisch → die Tische, das Buch → die Bücher**. Но окончания множественного числа бывают разными, поэтому их тоже лучше учить вместе со словом: **der Stuhl, die Stühle**.\n\n| Тип | Пример | Где встречается |\n| -e (часто с умлаутом) | der Tag → die Tage, der Stuhl → die Stühle | многие слова м. р. |\n| -er (с умлаутом) | das Kind → die Kinder, das Buch → die Bücher | многие слова ср. р. |\n| -(e)n | die Frau → die Frauen, die Lampe → die Lampen | большинство слов ж. р. |\n| -s | das Auto → die Autos, das Foto → die Fotos | иностранные слова, слова на -a, -o |\n| без окончания (иногда умлаут) | der Lehrer → die Lehrer, der Apfel → die Äpfel | слова на -er, -el, -en |\n\n**Полезные правила:**\n- Почти все слова женского рода получают **-(e)n**: **die Zeitung → die Zeitungen**.\n- Слова на **-chen** не меняются: **das Brötchen → die Brötchen**.\n- Умлаут бывает только у **a, o, u, au**: **der Bruder → die Brüder, das Haus → die Häuser**.\n- Отрицание во множественном числе — **keine**: **Ich habe keine Geschwister.**\n\n**Типичные ошибки русскоговорящих:**\n- Добавляют **-s** ко всему, как в английском: ✗ die Kinds, die Tischs → **die Kinder, die Tische**.\n- Добавляют лишнее окончание: ✗ die Lehrers, die Kinders → **die Lehrer, die Kinder**.\n- Используют **der/das** во множественном числе: ✗ das Bücher → **die Bücher**.\n- Забывают умлаут: ✗ die Apfel → **die Äpfel**.","q":[{"k":"mc","s":"Ich habe zwei ___.","o":["Kind","Kinder","Kinds"],"a":1,"ru":"У меня двое детей."},{"k":"mc","s":"___ Bücher sind neu.","o":["Der","Das","Die"],"a":2,"ru":"Книги новые."},{"k":"mc","s":"Wir kaufen drei ___.","o":["Äpfel","Apfels","Apfeln"],"a":0,"ru":"Мы покупаем три яблока."},{"k":"mc","s":"In der Stadt gibt es viele ___.","o":["Hotel","Hotelen","Hotele","Hotels"],"a":3,"ru":"В городе много гостиниц."},{"k":"type","s":"eine Frau – zwei ___ (Frau)","a":["Frauen"],"ru":"одна женщина – две женщины"},{"k":"type","s":"ein Auto – drei ___ (Auto)","a":["Autos"],"ru":"одна машина – три машины"},{"k":"type","s":"ein Stuhl – vier ___ (Stuhl)","a":["Stühle"],"ru":"один стул – четыре стула"},{"k":"type","s":"ein Lehrer – zwei ___ (Lehrer)","a":["Lehrer"],"ru":"один учитель – два учителя"},{"k":"order","w":["Kinder","spielen","die"],"a":["Die Kinder spielen"],"ru":"Дети играют."},{"k":"order","w":["sind","die","teuer","Tomaten"],"a":["Die Tomaten sind teuer","Teuer sind die Tomaten"],"ru":"Помидоры дорогие."},{"k":"tr","ru":"У меня два брата.","a":["Ich habe zwei Brüder"]},{"k":"tr","ru":"Где фотографии?","a":["Wo sind die Fotos","Wo sind die Bilder"]}]},{"id":"de-a1-akkusativ","lv":"A1","e":"🎯","t":"Винительный падеж (Akkusativ)","x":"Akkusativ отвечает на вопросы **wen? was?** (кого? что?) и обозначает прямое дополнение: **Ich kaufe einen Tisch.** — Я покупаю стол. Хорошая новость: меняется **только мужской род**.\n\n| | м. р. | ж. р. | ср. р. | мн. ч. |\n| Nominativ | der / ein / kein | die / eine / keine | das / ein / kein | die / — / keine |\n| Akkusativ | **den / einen / keinen** | die / eine / keine | das / ein / kein | die / — / keine |\n\n**Глаголы с Akkusativ:** haben, brauchen, kaufen, sehen, besuchen, kennen, lieben, trinken, essen, **es gibt** (есть, имеется): **Es gibt hier keinen Supermarkt.**\n\n**Личные местоимения в Akkusativ:**\n\n| Nom | ich | du | er | sie | es | wir | ihr | sie / Sie |\n| Akk | mich | dich | ihn | sie | es | uns | euch | sie / Sie |\n\n**Kennst du Tom? – Ja, ich kenne ihn.**\n\n**Предлоги, которые всегда требуют Akkusativ:** **für, ohne, durch, gegen, um**:\n- **Das ist für dich.** — Это для тебя.\n- **Ich trinke Kaffee ohne Zucker.**\n\n**Типичные ошибки русскоговорящих:**\n- Забывают изменить мужской род: ✗ Ich habe ein Bruder → **Ich habe einen Bruder**; ✗ Ich sehe der Film → **Ich sehe den Film**.\n- Изменяют женский и средний род по аналогии: ✗ Ich kaufe einen Lampe → **eine Lampe**.\n- Путают **ihn** (его) и **ihm** (ему — Dativ).\n- После **es gibt** ставят Nominativ: ✗ Es gibt ein Park → **Es gibt einen Park**.","q":[{"k":"mc","s":"Ich kaufe ___ Tisch.","o":["der","den","dem"],"a":1,"ru":"Я покупаю (этот) стол."},{"k":"mc","s":"Hast du ___ Bruder?","o":["einen","ein","eine"],"a":0,"ru":"У тебя есть брат?"},{"k":"mc","s":"Das Geschenk ist für ___.","o":["er","ihm","ihn"],"a":2,"ru":"Подарок для него."},{"k":"mc","s":"Es gibt hier ___ Supermarkt.","o":["kein","keiner","keinem","keinen"],"a":3,"ru":"Здесь нет супермаркета."},{"k":"type","s":"Ich liebe ___ (ты).","a":["dich"],"ru":"Я люблю тебя."},{"k":"type","s":"Wir besuchen ___ (der Onkel).","a":["den Onkel"],"ru":"Мы навещаем дядю."},{"k":"type","s":"Er trinkt ___ (ein) Tee.","a":["einen"],"ru":"Он пьёт чай."},{"k":"type","s":"Kennst du Tom? – Ja, ich kenne ___ (он) gut.","a":["ihn"],"ru":"Ты знаешь Тома? – Да, я хорошо его знаю."},{"k":"order","w":["den","ich","Film","sehe"],"a":["Ich sehe den Film","Den Film sehe ich"],"ru":"Я смотрю фильм."},{"k":"order","w":["für","das","dich","ist"],"a":["Das ist für dich","Für dich ist das"],"ru":"Это для тебя."},{"k":"tr","ru":"Я покупаю стул.","a":["Ich kaufe einen Stuhl","Ich kaufe den Stuhl"]},{"k":"tr","ru":"У него есть сын.","a":["Er hat einen Sohn"]}]},{"id":"de-a1-trennbare-verben","lv":"A1","e":"✂️","t":"Глаголы с отделяемыми приставками","x":"Многие немецкие глаголы имеют приставку, которая в настоящем времени **отделяется и уходит в конец предложения**. Глагол стоит на втором месте, приставка — в конце. Получается «рамка» (**Satzklammer**).\n\n| Инфинитив | Предложение |\n| aufstehen — вставать | Ich **stehe** um 7 Uhr **auf**. |\n| einkaufen — делать покупки | Wir **kaufen** im Supermarkt **ein**. |\n| anrufen — звонить | **Rufst** du mich morgen **an**? |\n| fernsehen — смотреть ТВ | Er **sieht** jeden Abend **fern**. |\n| mitkommen — пойти вместе | **Kommst** du **mit**? |\n| anfangen — начинаться | Der Film **fängt** um 8 **an**. |\n\n**Отделяемые приставки:** ab-, an-, auf-, aus-, ein-, mit-, vor-, weg-, zu-, zurück-, fern-. Они ударные: **AUFstehen, EINkaufen**.\n\n**Неотделяемые приставки:** be-, ge-, er-, ver-, zer-, ent-, emp-, miss-. Они безударные и никогда не отделяются: **Ich besuche meine Oma. Ich verstehe dich.**\n\nС модальным глаголом отделяемый глагол стоит в конце целиком: **Ich muss früh aufstehen.**\n\nСпряжение и смена гласной относятся к основе: **anfangen → er fängt an**, **fernsehen → du siehst fern**.\n\n**Типичные ошибки русскоговорящих:**\n- Не отделяют приставку: ✗ Ich aufstehe um 7 → **Ich stehe um 7 auf**.\n- Теряют приставку в длинном предложении: ✗ Ich rufe meine Mutter jeden Sonntag → **…jeden Sonntag an**. Без приставки смысл меняется!\n- Отделяют неотделяемые: ✗ Ich suche meine Oma be → **Ich besuche meine Oma**.","q":[{"k":"mc","s":"Ich stehe um 7 Uhr ___.","o":["an","auf","aus"],"a":1,"ru":"Я встаю в 7 часов."},{"k":"mc","s":"Wann ___ der Film an?","o":["fängt","anfängt","fangt"],"a":0,"ru":"Когда начинается фильм?"},{"k":"mc","s":"Kommst du heute Abend ___?","o":["auf","ein","mit"],"a":2,"ru":"Ты пойдёшь с нами сегодня вечером?"},{"k":"mc","s":"Ich ___ jeden Abend fern.","o":["fernsehe","sieht","sehen","sehe"],"a":3,"ru":"Я каждый вечер смотрю телевизор."},{"k":"type","s":"Ich ___ (einkaufen) im Supermarkt ein.","a":["kaufe"],"ru":"Я делаю покупки в супермаркете."},{"k":"type","s":"Du ___ (anrufen) mich morgen an.","a":["rufst"],"ru":"Ты позвонишь мне завтра."},{"k":"type","s":"Wir ___ (aufräumen) am Samstag die Wohnung auf.","a":["räumen"],"ru":"В субботу мы убираем квартиру."},{"k":"type","s":"Der Bus fährt um 9 Uhr ___ (abfahren).","a":["ab"],"ru":"Автобус отправляется в 9 часов."},{"k":"order","w":["auf","ich","um","sechs","stehe"],"a":["Ich stehe um sechs auf","Um sechs stehe ich auf"],"ru":"Я встаю в шесть."},{"k":"order","w":["mit","kommst","du"],"a":["Kommst du mit"],"ru":"Ты пойдёшь с нами?"},{"k":"tr","ru":"Поезд прибывает в 10 часов.","a":["Der Zug kommt um 10 Uhr an","Um 10 Uhr kommt der Zug an","Der Zug kommt um zehn Uhr an","Um zehn Uhr kommt der Zug an","Der Zug kommt um 10 an","Der Zug kommt um zehn an"]},{"k":"tr","ru":"Я звоню маме.","a":["Ich rufe meine Mutter an","Ich rufe Mama an","Ich rufe meine Mama an"]}]},{"id":"de-a1-modalverben","lv":"A1","e":"💪","t":"Модальные глаголы: können, müssen, wollen, möchten, dürfen, sollen","x":"Модальные глаголы выражают возможность, необходимость, желание. Модальный глагол спрягается и стоит на **втором месте**, а основной глагол в **инфинитиве** уходит **в конец**: **Ich kann gut schwimmen.**\n\n| | können | müssen | wollen | möchten | dürfen | sollen |\n| ich | kann | muss | will | möchte | darf | soll |\n| du | kannst | musst | willst | möchtest | darfst | sollst |\n| er / sie / es | kann | muss | will | möchte | darf | soll |\n| wir | können | müssen | wollen | möchten | dürfen | sollen |\n| ihr | könnt | müsst | wollt | möchtet | dürft | sollt |\n| sie / Sie | können | müssen | wollen | möchten | dürfen | sollen |\n\nОбратите внимание: у **ich** и **er** формы одинаковые и **без окончания**; в единственном числе часто меняется гласная.\n\n**Значения:**\n- **können** — мочь, уметь: **Kannst du Deutsch sprechen?**\n- **müssen** — быть должным, надо: **Ich muss heute arbeiten.**\n- **wollen** — хотеть (твёрдо): **Er will Arzt werden.**\n- **möchten** — хотел бы (вежливо): **Ich möchte einen Kaffee.**\n- **dürfen** — иметь разрешение: **Hier darf man nicht rauchen.** — Здесь нельзя курить.\n- **sollen** — следует (по чужому указанию): **Der Arzt sagt, ich soll viel schlafen.**\n\n**Типичные ошибки русскоговорящих:**\n- Ставят **zu** перед инфинитивом: ✗ Ich kann zu schwimmen → **Ich kann schwimmen**.\n- Добавляют окончание: ✗ er kannt, ich musse → **er kann, ich muss**.\n- Путают **muss nicht** (не нужно) и **darf nicht** (нельзя): **Du musst nicht kommen** — тебе не обязательно приходить; **Du darfst nicht kommen** — тебе нельзя приходить.","q":[{"k":"mc","s":"Ich ___ gut schwimmen.","o":["kann","kannst","können"],"a":0,"ru":"Я хорошо умею плавать."},{"k":"mc","s":"Hier ___ man nicht rauchen.","o":["muss","darf","will"],"a":1,"ru":"Здесь нельзя курить."},{"k":"mc","s":"___ ihr morgen kommen?","o":["Kannst","Können","Könnt"],"a":2,"ru":"Вы (ребята) можете прийти завтра?"},{"k":"mc","s":"Ich ___ einen Kaffee, bitte.","o":["möchtest","möchten","mag","möchte"],"a":3,"ru":"Я бы хотел кофе, пожалуйста."},{"k":"type","s":"Du ___ (müssen) heute arbeiten.","a":["musst"],"ru":"Тебе нужно сегодня работать."},{"k":"type","s":"Er ___ (wollen) Arzt werden.","a":["will"],"ru":"Он хочет стать врачом."},{"k":"type","s":"Wir ___ (können) heute nicht kommen.","a":["können"],"ru":"Мы не можем прийти сегодня."},{"k":"type","s":"Was ___ (möchten) Sie trinken?","a":["möchten"],"ru":"Что Вы хотели бы выпить?"},{"k":"order","w":["muss","ich","lernen","heute"],"a":["Ich muss heute lernen","Heute muss ich lernen"],"ru":"Сегодня мне нужно учиться."},{"k":"order","w":["Deutsch","kannst","sprechen","du"],"a":["Kannst du Deutsch sprechen"],"ru":"Ты умеешь говорить по-немецки?"},{"k":"tr","ru":"Я хочу купить машину.","a":["Ich will ein Auto kaufen","Ich möchte ein Auto kaufen","Ich will einen Wagen kaufen","Ich möchte einen Wagen kaufen"]},{"k":"tr","ru":"Здесь нельзя парковаться.","a":["Hier darf man nicht parken","Man darf hier nicht parken","Hier kann man nicht parken","Man kann hier nicht parken"]}]},{"id":"de-a2-possessivartikel","lv":"A2","e":"🏠","t":"Притяжательные артикли: mein, dein, sein, ihr…","x":"Притяжательные артикли показывают, кому что принадлежит. Каждому личному местоимению соответствует свой артикль:\n\n| ich | du | er / es | sie | wir | ihr | sie | Sie |\n| mein | dein | sein | ihr | unser | euer | ihr | Ihr |\n\nОкончания у них такие же, как у **ein / kein**:\n\n| | м. р. | ж. р. | ср. р. | мн. ч. |\n| Nominativ | mein Bruder | meine Schwester | mein Kind | meine Eltern |\n| Akkusativ | **meinen** Bruder | meine Schwester | mein Kind | meine Eltern |\n\n**euer** теряет **e** при окончании: **eure Jacken, euren Hund**.\n\n**Выбор артикля зависит от двух вещей:**\n- **кто владелец** → выбираем слово: у Тома — **sein**, у Марии — **ihr**;\n- **род, число и падеж предмета** → выбираем окончание: **Tom sucht seinen Schlüssel** (der Schlüssel, Akk.), **Maria ruft ihre Mutter an** (die Mutter).\n\n**Ihr** с большой буквы — «Ваш»: **Frau Weber, ist das Ihr Mantel?**\n\n**Типичные ошибки русскоговорящих:**\n- В немецком нет слова «свой». Его переводят по лицу владельца: **Ich nehme meine Tasche. Er liebt seine Frau. Sie liebt ihren Mann. Wir besuchen unsere Oma.**\n- Путают **sein** и **ihr**: «его» → **sein**, «её» и «их» → **ihr**. ✗ Maria sucht seine Tasche (если сумка Марии) → **Maria sucht ihre Tasche**.\n- Забывают окончание в Akkusativ: ✗ Hast du dein Pass? → **Hast du deinen Pass?**\n- Выбирают окончание по полу владельца, а не по роду предмета: **ihr Mann** (der Mann), **seine Frau** (die Frau).","q":[{"k":"mc","s":"Das ist ___ Schwester Anna.","o":["mein","meine","meinen"],"a":1,"ru":"Это моя сестра Анна."},{"k":"mc","s":"Tom sucht ___ Schlüssel.","o":["seinen","sein","ihren"],"a":0,"ru":"Том ищет свой ключ."},{"k":"mc","s":"Maria ruft ___ Mutter an.","o":["seine","ihren","ihre"],"a":2,"ru":"Мария звонит своей маме."},{"k":"mc","s":"Kinder, wo sind ___ Jacken?","o":["unser","euer","ihre","eure"],"a":3,"ru":"Дети, где ваши куртки?"},{"k":"type","s":"Frau Weber, ist das ___ (Ваш) Mantel?","a":["Ihr"],"ru":"Госпожа Вебер, это Ваше пальто?"},{"k":"type","s":"Wir besuchen ___ (наша) Oma.","a":["unsere"],"ru":"Мы навещаем нашу бабушку."},{"k":"type","s":"Hast du ___ (твой) Pass?","a":["deinen"],"ru":"У тебя есть твой паспорт (с собой)?"},{"k":"type","s":"Peter und Lisa verkaufen ___ (их) Auto.","a":["ihr"],"ru":"Петер и Лиза продают свою машину."},{"k":"order","w":["ist","Bruder","das","mein"],"a":["Das ist mein Bruder"],"ru":"Это мой брат."},{"k":"order","w":["seine","liebt","Frau","er"],"a":["Er liebt seine Frau","Seine Frau liebt er"],"ru":"Он любит свою жену."},{"k":"tr","ru":"Она ищет свою сумку.","a":["Sie sucht ihre Tasche"]},{"k":"tr","ru":"Где твой телефон?","a":["Wo ist dein Telefon","Wo ist dein Handy"]}]},{"id":"de-a2-imperativ","lv":"A2","e":"📢","t":"Повелительное наклонение (Imperativ)","x":"Imperativ — это просьба, совет, указание или команда. Есть три формы: для **du**, для **ihr** и для **Sie**.\n\n| Инфинитив | du | ihr | Sie |\n| kommen | Komm! | Kommt! | Kommen Sie! |\n| warten | Warte! | Wartet! | Warten Sie! |\n| nehmen | Nimm! | Nehmt! | Nehmen Sie! |\n| fahren | Fahr! | Fahrt! | Fahren Sie! |\n| aufmachen | Mach auf! | Macht auf! | Machen Sie auf! |\n| sein | Sei! | Seid! | Seien Sie! |\n\n**Как образовать:**\n- **du**: форма **du** без **-st** и без местоимения: du kommst → **Komm!** После **-t, -d** обычно добавляется **-e**: **Warte! Finde!**\n- Смена **e → i / ie** сохраняется: du sprichst → **Sprich!**, du liest → **Lies!**, du isst → **Iss!**\n- Смена **a → ä** исчезает: du fährst → **Fahr!**, du schläfst → **Schlaf!**\n- **ihr**: форма **ihr** без местоимения: **Kommt! Lest!**\n- **Sie**: глагол + **Sie**: **Kommen Sie bitte herein!**\n\nОтделяемая приставка уходит в конец: **Mach bitte die Tür zu!** Слово **bitte** делает просьбу вежливой и может стоять в разных местах.\n\n**Типичные ошибки русскоговорящих:**\n- Оставляют местоимение: ✗ Du komm! → **Komm!**\n- Сохраняют умлаут: ✗ Fähr langsam! → **Fahr langsam!**\n- Не меняют e → i: ✗ Nehm das!, ✗ Les! → **Nimm das!**, **Lies!**\n- Забывают **Sie** в вежливой форме: ✗ Kommen bitte! → **Kommen Sie bitte!**","q":[{"k":"mc","s":"___ bitte langsam, Anna!","o":["Sprich","Sprech","Sprichst"],"a":0,"ru":"Говори, пожалуйста, медленно, Анна!"},{"k":"mc","s":"Herr Klein, ___ bitte Platz!","o":["nimm","nehmen Sie","nehmt"],"a":1,"ru":"Господин Кляйн, садитесь, пожалуйста!"},{"k":"mc","s":"Kinder, ___ leise!","o":["sei","seien","seid"],"a":2,"ru":"Дети, тише!"},{"k":"mc","s":"Max, ___ nicht so schnell!","o":["fährst","fähr","fahrt","fahr"],"a":3,"ru":"Макс, не езди так быстро!"},{"k":"type","s":"___ (lesen, du) den Text!","a":["Lies"],"ru":"Прочитай текст!"},{"k":"type","s":"___ (warten, ihr) hier!","a":["Wartet"],"ru":"Подождите (ребята) здесь!"},{"k":"type","s":"Mach bitte das Fenster ___ (aufmachen)!","a":["auf"],"ru":"Открой, пожалуйста, окно!"},{"k":"type","s":"___ (kommen, Sie) bitte herein!","a":["Kommen Sie"],"ru":"Входите, пожалуйста!"},{"k":"order","w":["die","Tür","mach","zu"],"a":["Mach die Tür zu"],"ru":"Закрой дверь!"},{"k":"order","w":["Sie","bitte","hier","unterschreiben"],"a":["Unterschreiben Sie bitte hier","Unterschreiben Sie hier bitte","Bitte unterschreiben Sie hier"],"ru":"Подпишите, пожалуйста, здесь."},{"k":"tr","ru":"Помоги мне, пожалуйста!","a":["Hilf mir bitte","Bitte hilf mir"]},{"k":"tr","ru":"Не забудьте (Вы) паспорт!","a":["Vergessen Sie den Pass nicht","Vergessen Sie Ihren Pass nicht","Vergessen Sie den Reisepass nicht","Vergessen Sie Ihren Reisepass nicht"]}]},{"id":"de-a2-dativ","lv":"A2","e":"🎁","t":"Дательный падеж (Dativ) и предлоги с ним","x":"Dativ отвечает на вопрос **wem?** (кому?) и обозначает косвенное дополнение — получателя: **Ich gebe dem Lehrer das Buch.** — Я даю учителю книгу.\n\n| | м. р. | ж. р. | ср. р. | мн. ч. |\n| определённый | dem | der | dem | den …**n** |\n| неопределённый | einem | einer | einem | — |\n| притяжательный | meinem | meiner | meinem | meinen …**n** |\n\nВо множественном числе к существительному добавляется **-n**: **mit den Kindern** (если слово не кончается на -n или -s).\n\n**Местоимения:**\n\n| Nom | ich | du | er | sie | es | wir | ihr | sie / Sie |\n| Dat | mir | dir | ihm | ihr | ihm | uns | euch | ihnen / Ihnen |\n\n**Глаголы с Dativ:** helfen, danken, gefallen, gehören, schmecken, antworten, gratulieren; **geben, schenken, zeigen** (кому + что): **Das Buch gehört mir. Wie gefällt dir die Stadt?**\n\n**Предлоги, всегда требующие Dativ:** **aus, bei, mit, nach, seit, von, zu**. Слияния: **zum** (zu dem), **zur** (zu der), **beim**, **vom**.\n- **Ich fahre mit dem Bus.**\n- **Ich wohne seit einem Jahr in Wien.**\n- **Wir gehen zur Ärztin.**\n\n**Типичные ошибки русскоговорящих:**\n- После **mit** ставят Akkusativ: ✗ mit den Bus → **mit dem Bus**.\n- «Нравиться» строят как по-русски, но забывают Dativ: «мне нравится» = **mir gefällt**, а не ✗ ich gefällt.\n- **danken** — Dativ (благодарить **кого** → кому): **Ich danke Ihnen.** Зато **fragen** — Akkusativ: **Ich frage dich.**\n- Забывают **-n** во множественном числе: ✗ mit den Kinder → **mit den Kindern**.","q":[{"k":"mc","s":"Ich fahre mit ___ Bus.","o":["den","dem","der"],"a":1,"ru":"Я еду на автобусе."},{"k":"mc","s":"Das Buch gehört ___.","o":["mir","mich","ich"],"a":0,"ru":"Книга принадлежит мне."},{"k":"mc","s":"Wir gehen zu ___ Ärztin.","o":["dem","den","der"],"a":2,"ru":"Мы идём к врачу (женщине)."},{"k":"mc","s":"Ich danke ___ für die Hilfe.","o":["Sie","Ihr","Ihre","Ihnen"],"a":3,"ru":"Я благодарю Вас за помощь."},{"k":"type","s":"Kannst du ___ (я) helfen?","a":["mir"],"ru":"Ты можешь мне помочь?"},{"k":"type","s":"Ich wohne seit ___ (ein) Jahr in Wien.","a":["einem"],"ru":"Я живу в Вене уже год."},{"k":"type","s":"Er spielt mit ___ (die Kinder).","a":["den Kindern"],"ru":"Он играет с детьми."},{"k":"type","s":"Wie gefällt ___ (она) die Stadt?","a":["ihr"],"ru":"Как ей нравится город?"},{"k":"order","w":["gebe","ich","dem","das","Buch","Lehrer"],"a":["Ich gebe dem Lehrer das Buch","Ich gebe das Buch dem Lehrer","Das Buch gebe ich dem Lehrer","Dem Lehrer gebe ich das Buch"],"ru":"Я даю учителю книгу."},{"k":"order","w":["schmeckt","Suppe","dir","die"],"a":["Schmeckt dir die Suppe","Schmeckt die Suppe dir"],"ru":"Тебе нравится (на вкус) суп?"},{"k":"tr","ru":"Я еду к своему другу.","a":["Ich fahre zu meinem Freund"]},{"k":"tr","ru":"Мне нравится эта квартира.","a":["Mir gefällt diese Wohnung","Diese Wohnung gefällt mir","Ich mag diese Wohnung"]}]},{"id":"de-a2-perfekt","lv":"A2","e":"⏮️","t":"Прошедшее время Perfekt","x":"Perfekt — главное прошедшее время в разговорной речи. Оно состоит из двух частей: **haben** или **sein** (на втором месте) + **Partizip II** (в конце): **Ich habe Kaffee getrunken.** — Я выпил кофе.\n\n**Как образуется Partizip II:**\n\n| Тип | Инфинитив | Partizip II |\n| правильные: ge-…-t | machen, arbeiten | gemacht, gearbeitet |\n| неправильные: ge-…-en | schreiben, trinken, essen | geschrieben, getrunken, gegessen |\n| отделяемые: приставка + ge | einkaufen, aufstehen | eingekauft, aufgestanden |\n| без ge-: be-, ver-, er-… | besuchen, verstehen | besucht, verstanden |\n| без ge-: на -ieren | studieren, telefonieren | studiert, telefoniert |\n\nФормы неправильных глаголов нужно учить: **gehen – gegangen, kommen – gekommen, schlafen – geschlafen, fliegen – geflogen**.\n\n**haben или sein?**\n- Большинство глаголов — с **haben**: **Wir haben Pizza gegessen.**\n- С **sein** — глаголы движения из точки в точку и изменения состояния: **gehen, fahren, kommen, fliegen, aufstehen, einschlafen**, а также **sein, bleiben, passieren**: **Gestern bin ich ins Kino gegangen. Wann seid ihr aufgestanden?**\n\n**Типичные ошибки русскоговорящих:**\n- Ставят **haben** с глаголами движения: ✗ Ich habe gegangen → **Ich bin gegangen**.\n- Добавляют **ge-** где не нужно: ✗ gestudiert, gebesucht → **studiert, besucht**.\n- Ставят ge- перед приставкой: ✗ geeinkauft → **eingekauft**.\n- Не уносят Partizip в конец: ✗ Ich habe getrunken Kaffee → **Ich habe Kaffee getrunken**.","q":[{"k":"mc","s":"Gestern ___ ich ins Kino gegangen.","o":["habe","bin","war"],"a":1,"ru":"Вчера я ходил в кино."},{"k":"mc","s":"Wir haben Pizza ___.","o":["gegessen","geesst","gegesst"],"a":0,"ru":"Мы ели пиццу."},{"k":"mc","s":"Hast du die Hausaufgaben ___?","o":["gemachen","machte","gemacht"],"a":2,"ru":"Ты сделал домашнее задание?"},{"k":"mc","s":"Er hat in Berlin ___.","o":["gestudiert","studieren","studierte","studiert"],"a":3,"ru":"Он учился (в вузе) в Берлине."},{"k":"type","s":"Ich habe meine Oma ___ (besuchen).","a":["besucht"],"ru":"Я навестил бабушку."},{"k":"type","s":"Wann ___ (sein/haben) ihr aufgestanden?","a":["seid"],"ru":"Когда вы (ребята) встали?"},{"k":"type","s":"Sie hat einen Brief ___ (schreiben).","a":["geschrieben"],"ru":"Она написала письмо."},{"k":"type","s":"Wir haben gestern ___ (einkaufen).","a":["eingekauft"],"ru":"Вчера мы ходили за покупками."},{"k":"order","w":["ich","habe","Kaffee","getrunken"],"a":["Ich habe Kaffee getrunken","Kaffee habe ich getrunken"],"ru":"Я выпил кофе."},{"k":"order","w":["nach","Spanien","sind","geflogen","wir"],"a":["Wir sind nach Spanien geflogen","Nach Spanien sind wir geflogen"],"ru":"Мы полетели в Испанию."},{"k":"tr","ru":"Я долго спал.","a":["Ich habe lange geschlafen","Lange habe ich geschlafen"]},{"k":"tr","ru":"Она приехала вчера.","a":["Sie ist gestern gekommen","Gestern ist sie gekommen","Sie ist gestern angekommen","Gestern ist sie angekommen"]}]},{"id":"de-a2-wechselpraepositionen","lv":"A2","e":"📍","t":"Предлоги места: Wo? + Dativ, Wohin? + Akkusativ","x":"Девять предлогов могут требовать и Dativ, и Akkusativ — их называют **Wechselpräpositionen**: **an, auf, hinter, in, neben, über, unter, vor, zwischen**.\n\n- **Wo?** (где?) — место, нет движения к цели → **Dativ**: **Das Buch liegt auf dem Tisch.**\n- **Wohin?** (куда?) — направление, движение к цели → **Akkusativ**: **Ich lege das Buch auf den Tisch.**\n\nРусский язык работает похоже: «в школе» (где?) — «в школу» (куда?).\n\n| Предлог | Wo? (Dativ) | Wohin? (Akk) |\n| in | Ich bin in der Küche. | Ich gehe in die Küche. |\n| auf | Die Vase steht auf dem Tisch. | Ich stelle die Vase auf den Tisch. |\n| an | Das Bild hängt an der Wand. | Ich hänge das Bild an die Wand. |\n| unter | Die Katze schläft unter dem Bett. | Die Katze läuft unter das Bett. |\n\n**Пары глаголов:**\n- **stellen** (ставить, куда?) — **stehen** (стоять, где?)\n- **legen** (класть) — **liegen** (лежать)\n- **hängen** (вешать) — **hängen** (висеть)\n- **setzen** (сажать) — **sitzen** (сидеть)\n\n**Слияния:** in dem → **im**, in das → **ins**, an dem → **am**, an das → **ans**: **Ich arbeite im Büro. Wir gehen ins Kino.**\n\n**Типичные ошибки русскоговорящих:**\n- Ставят Dativ при движении: ✗ Ich gehe in der Küche → **Ich gehe in die Küche**.\n- Путают **stellen / stehen**, **legen / liegen**: ✗ Das Buch legt auf dem Tisch → **Das Buch liegt auf dem Tisch**.\n- Переводят «на» всегда как **auf**: на стене — **an der Wand**.","q":[{"k":"mc","s":"Das Buch liegt auf ___ Tisch.","o":["den","dem","der"],"a":1,"ru":"Книга лежит на столе."},{"k":"mc","s":"Ich stelle die Vase auf ___ Tisch.","o":["den","dem","der"],"a":0,"ru":"Я ставлю вазу на стол."},{"k":"mc","s":"Wir gehen heute ___ Kino.","o":["im","am","ins"],"a":2,"ru":"Сегодня мы идём в кино."},{"k":"mc","s":"Das Bild hängt an ___ Wand.","o":["die","den","dem","der"],"a":3,"ru":"Картина висит на стене."},{"k":"type","s":"Die Katze schläft unter ___ (das Bett, где?).","a":["dem Bett"],"ru":"Кошка спит под кроватью."},{"k":"type","s":"Ich lege das Handy in ___ (die Tasche, куда?).","a":["die Tasche"],"ru":"Я кладу телефон в сумку."},{"k":"type","s":"Mein Bruder arbeitet ___ (in + dem) Büro.","a":["im"],"ru":"Мой брат работает в офисе."},{"k":"type","s":"Häng die Jacke bitte in ___ (der Schrank, куда?)!","a":["den Schrank"],"ru":"Повесь, пожалуйста, куртку в шкаф!"},{"k":"order","w":["dem","steht","Auto","vor","das","Haus"],"a":["Das Auto steht vor dem Haus","Vor dem Haus steht das Auto"],"ru":"Машина стоит перед домом."},{"k":"order","w":["ich","die","Küche","gehe","in"],"a":["Ich gehe in die Küche","In die Küche gehe ich"],"ru":"Я иду на кухню."},{"k":"tr","ru":"Ключ лежит на столе.","a":["Der Schlüssel liegt auf dem Tisch"]},{"k":"tr","ru":"Я вешаю картину на стену.","a":["Ich hänge das Bild an die Wand","Ich hänge ein Bild an die Wand"]}]},{"id":"de-a2-praeteritum-sein-haben-modal","lv":"A2","e":"📜","t":"Präteritum глаголов sein, haben и модальных глаголов","x":"В разговорной речи прошлое обычно выражается через Perfekt. Но глаголы **sein, haben** и **модальные глаголы** даже в разговоре чаще употребляются в **Präteritum** — это короче и естественнее: **Gestern war ich krank.** (а не «bin gewesen»).\n\n| | sein | haben | können | müssen | wollen | dürfen |\n| ich | war | hatte | konnte | musste | wollte | durfte |\n| du | warst | hattest | konntest | musstest | wolltest | durftest |\n| er / sie / es | war | hatte | konnte | musste | wollte | durfte |\n| wir | waren | hatten | konnten | mussten | wollten | durften |\n| ihr | wart | hattet | konntet | musstet | wolltet | durftet |\n| sie / Sie | waren | hatten | konnten | mussten | wollten | durften |\n\n**Обратите внимание:**\n- У **ich** и **er/sie/es** формы одинаковые.\n- У модальных глаголов в Präteritum **нет умлаута**: können → **konnte**, müssen → **musste**, dürfen → **durfte**.\n- **sollen → sollte**; у **möchten** нет своего Präteritum, вместо него — **wollte**: **Ich wollte Kaffee trinken.**\n- Инфинитив при модальном глаголе по-прежнему в конце: **Als Kind konnte er nicht schwimmen.**\n\n**Типичные ошибки русскоговорящих:**\n- Строят громоздкий Perfekt: ✗ Ich habe gewesen (ещё и с haben!) → **Ich war** или **Ich bin gewesen**.\n- Ставят умлаут: ✗ Ich könnte nicht kommen (это «я мог бы») → **Ich konnte nicht kommen** (я не мог).\n- Путают формы **wart** (ihr) и **wartet** (от warten — ждать).","q":[{"k":"mc","s":"Gestern ___ ich krank.","o":["war","bin","hatte"],"a":0,"ru":"Вчера я был болен."},{"k":"mc","s":"Wir ___ keine Zeit.","o":["waren","hatten","hattet"],"a":1,"ru":"У нас не было времени."},{"k":"mc","s":"Als Kind ___ er nicht schwimmen.","o":["könnte","kann","konnte"],"a":2,"ru":"В детстве он не умел плавать."},{"k":"mc","s":"___ ihr letzte Woche in Paris?","o":["Waren","War","Warst","Wart"],"a":3,"ru":"Вы (ребята) были на прошлой неделе в Париже?"},{"k":"type","s":"Du ___ (haben, Präteritum) Glück.","a":["hattest"],"ru":"Тебе повезло."},{"k":"type","s":"Ich ___ (müssen, Präteritum) lange warten.","a":["musste"],"ru":"Мне пришлось долго ждать."},{"k":"type","s":"Wo ___ (sein, Präteritum) du am Wochenende?","a":["warst"],"ru":"Где ты был на выходных?"},{"k":"type","s":"Sie ___ (wollen, Präteritum) Ärztin werden.","a":["wollte"],"ru":"Она хотела стать врачом."},{"k":"order","w":["ich","gestern","arbeiten","musste"],"a":["Ich musste gestern arbeiten","Gestern musste ich arbeiten"],"ru":"Вчера мне нужно было работать."},{"k":"order","w":["Party","war","toll","die"],"a":["Die Party war toll","Toll war die Party"],"ru":"Вечеринка была классной."},{"k":"tr","ru":"У нас была собака.","a":["Wir hatten einen Hund"]},{"k":"tr","ru":"Я не мог прийти.","a":["Ich konnte nicht kommen"]}]},{"id":"de-a2-komparation","lv":"A2","e":"📈","t":"Сравнение прилагательных: Komparativ и Superlativ","x":"Прилагательные и наречия имеют три степени: **schnell – schneller – am schnellsten** (быстрый – быстрее – быстрее всего).\n\n| Положительная | Komparativ (-er) | Superlativ (am -sten) |\n| schnell | schneller | am schnellsten |\n| klein | kleiner | am kleinsten |\n| alt | älter | am ältesten |\n| groß | größer | am größten |\n| kalt | kälter | am kältesten |\n| lang | länger | am längsten |\n| gut | besser | am besten |\n| viel | mehr | am meisten |\n| gern | lieber | am liebsten |\n| hoch | höher | am höchsten |\n\n**Правила:**\n- Многие короткие прилагательные получают **умлаут**: alt → älter, jung → jünger, warm → wärmer, kurz → kürzer.\n- После **-d, -t, -s, -ß, -z** в Superlativ вставляется **-e-**: **am ältesten, am kürzesten**.\n- **gut, viel, gern, hoch** — особые формы, их нужно запомнить.\n\n**Сравнение:**\n- неравенство — **als** (чем): **Berlin ist größer als München.**\n- равенство — **so … wie** (такой же, как): **Mein Bruder ist so alt wie ich.**\n\n**gern / lieber / am liebsten** — с глаголом выражает предпочтение: **Ich trinke lieber Tee als Kaffee. Am liebsten trinke ich Wasser.**\n\n**Типичные ошибки русскоговорящих:**\n- Строят сравнение через «более»: ✗ mehr schön → **schöner**.\n- Путают **als** и **wie**: ✗ größer wie → **größer als**; ✗ so alt als → **so alt wie**.\n- Забывают умлаут или особые формы: ✗ alter, guter, gerner → **älter, besser, lieber**.","q":[{"k":"mc","s":"Berlin ist größer ___ München.","o":["wie","als","so"],"a":1,"ru":"Берлин больше Мюнхена."},{"k":"mc","s":"Mein Bruder ist so alt ___ ich.","o":["wie","als","dann"],"a":0,"ru":"Мой брат такого же возраста, как я."},{"k":"mc","s":"Ich trinke ___ Tee als Kaffee.","o":["gerner","mehr gern","lieber"],"a":2,"ru":"Я предпочитаю чай кофе."},{"k":"mc","s":"Im Juli ist es am ___.","o":["warmsten","wärmer","wärmste","wärmsten"],"a":3,"ru":"В июле теплее всего."},{"k":"type","s":"Der Zug ist ___ (schnell, Komparativ) als der Bus.","a":["schneller"],"ru":"Поезд быстрее автобуса."},{"k":"type","s":"Anna singt am ___ (gut, Superlativ).","a":["besten"],"ru":"Анна поёт лучше всех."},{"k":"type","s":"Heute ist es ___ (kalt, Komparativ) als gestern.","a":["kälter"],"ru":"Сегодня холоднее, чем вчера."},{"k":"type","s":"Wer arbeitet am ___ (viel, Superlativ)?","a":["meisten"],"ru":"Кто работает больше всех?"},{"k":"order","w":["ist","älter","Schwester","meine","als","ich"],"a":["Meine Schwester ist älter als ich"],"ru":"Моя сестра старше меня."},{"k":"order","w":["Russisch","ist","Deutsch","so","schwer","wie"],"a":["Deutsch ist so schwer wie Russisch","Russisch ist so schwer wie Deutsch"],"ru":"Немецкий такой же трудный, как русский."},{"k":"tr","ru":"Моя квартира меньше твоей.","a":["Meine Wohnung ist kleiner als deine","Meine Wohnung ist kleiner als deine Wohnung"]},{"k":"tr","ru":"Летом дни длиннее.","a":["Im Sommer sind die Tage länger","Die Tage sind im Sommer länger"]}]},{"id":"de-a2-nebensaetze","lv":"A2","e":"🔗","t":"Придаточные предложения: weil, dass, wenn","x":"В придаточном предложении (**Nebensatz**) спрягаемый глагол стоит **в самом конце**. Придаточное отделяется запятой.\n\n| Союз | Значение | Пример |\n| weil | потому что | Ich bleibe zu Hause, weil ich krank **bin**. |\n| dass | что | Ich glaube, dass er heute **kommt**. |\n| wenn | если, когда | Wenn ich Zeit **habe**, lese ich ein Buch. |\n\n**Что уходит в конец:**\n- отделяемый глагол — целиком: **…, dass Anna morgen ankommt.**\n- при модальном глаголе — сначала инфинитив, потом модальный: **…, weil ich arbeiten muss.**\n- в Perfekt — сначала Partizip, потом вспомогательный: **…, weil ich krank gewesen bin.**\n\n**Если придаточное стоит первым**, оно занимает первое место, и главное предложение начинается с глагола: **Wenn das Wetter gut ist, gehen wir spazieren.** (глагол — глагол через запятую).\n\n**weil и denn** значат одно и то же, но после **denn** порядок прямой: **Ich komme nicht, denn ich habe keine Zeit.** = **Ich komme nicht, weil ich keine Zeit habe.**\n\n**Типичные ошибки русскоговорящих:**\n- Оставляют глагол на втором месте: ✗ weil ich bin krank → **weil ich krank bin**.\n- После придаточного ставят подлежащее перед глаголом: ✗ Wenn ich Zeit habe, ich lese → **…, lese ich**.\n- Путают **dass** (союз «что») и **das** (артикль/местоимение «это»).\n- Отделяют приставку в придаточном: ✗ dass er morgen kommt an → **dass er morgen ankommt**.","q":[{"k":"mc","s":"Ich bleibe zu Hause, weil ich krank ___.","o":["bin","sein","ist"],"a":0,"ru":"Я остаюсь дома, потому что я болен."},{"k":"mc","s":"Ich glaube, ___ er heute kommt.","o":["das","dass","wenn"],"a":1,"ru":"Я думаю, что он сегодня придёт."},{"k":"mc","s":"___ das Wetter gut ist, gehen wir spazieren.","o":["Dass","Denn","Wenn"],"a":2,"ru":"Если погода хорошая, мы идём гулять."},{"k":"mc","s":"Er sagt, dass er keine Zeit ___.","o":["hast","haben","hatten","hat"],"a":3,"ru":"Он говорит, что у него нет времени."},{"k":"type","s":"Ich lerne Deutsch, weil ich in Deutschland arbeiten ___ (möchten).","a":["möchte"],"ru":"Я учу немецкий, потому что хочу работать в Германии."},{"k":"type","s":"Weißt du, dass Anna morgen ___ (ankommen)?","a":["ankommt"],"ru":"Ты знаешь, что Анна приезжает завтра?"},{"k":"type","s":"Wenn ich Zeit habe, ___ (lesen) ich ein Buch.","a":["lese"],"ru":"Когда у меня есть время, я читаю книгу."},{"k":"type","s":"Ich hoffe, ___ (что) du gesund bist.","a":["dass"],"ru":"Я надеюсь, что ты здоров."},{"k":"order","w":["ich","schlafe","weil","müde","bin","ich"],"a":["Ich schlafe weil ich müde bin","Weil ich müde bin schlafe ich"],"ru":"Я сплю, потому что устал."},{"k":"order","w":["dass","ich","weiß","er","kommt"],"a":["Ich weiß dass er kommt","Dass er kommt weiß ich"],"ru":"Я знаю, что он придёт."},{"k":"tr","ru":"Я не приду, потому что у меня нет времени.","a":["Ich komme nicht, weil ich keine Zeit habe","Weil ich keine Zeit habe, komme ich nicht","Ich komme nicht, denn ich habe keine Zeit"]},{"k":"tr","ru":"Я думаю, что это хорошая идея.","a":["Ich denke, dass das eine gute Idee ist","Ich glaube, dass das eine gute Idee ist","Ich finde, dass das eine gute Idee ist","Ich denke, dass es eine gute Idee ist","Ich glaube, dass es eine gute Idee ist","Ich denke, das ist eine gute Idee","Ich glaube, das ist eine gute Idee","Ich finde, das ist eine gute Idee"]}]},{"id":"de-b1-reflexive-verben","lv":"B1","e":"🪞","t":"Возвратные глаголы (sich freuen, sich interessieren…)","x":"Возвратные глаголы употребляются с местоимением **sich**, которое меняется по лицам. В русском языке ему часто соответствует **-ся**: **sich freuen** — радоваться.\n\n| Лицо | Akkusativ | Dativ |\n| ich | mich | mir |\n| du | dich | dir |\n| er / sie / es | sich | sich |\n| wir | uns | uns |\n| ihr | euch | euch |\n| sie / Sie | sich | sich |\n\n**Akkusativ** — обычный случай: **Ich freue mich. Wir treffen uns um acht.**\n**Dativ** — если в предложении уже есть дополнение в Akkusativ: **Ich putze mir die Zähne. Ziehst du dir die Jacke an?** (но: **Ich ziehe mich an.**)\n\n**Частые глаголы с предлогами:**\n- **sich freuen auf** (+Akk) — радоваться предстоящему; **sich freuen über** — радоваться тому, что есть\n- **sich interessieren für** — интересоваться\n- **sich erinnern an** — вспоминать, помнить\n- **sich ärgern über** — злиться\n- а также: **sich beeilen, sich erholen, sich ausruhen, sich vorstellen, sich anziehen, sich melden**\n\n**Место sich:** сразу после спрягаемого глагола; при инверсии — после местоимения-подлежащего: **Morgen melde ich mich.** В Perfekt — всегда с **haben**: **Ich habe mich gefreut.**\n\n**Типичные ошибки русскоговорящих:**\n- Считают, что «-ся» всегда = **sich**: **учиться — lernen**, **начинаться — anfangen**, **нравиться — gefallen** без sich.\n- И наоборот, забывают sich там, где в русском его нет: **отдыхать — sich erholen**, **спешить — sich beeilen**: ✗ Ich beeile → **Ich beeile mich**.\n- Ставят Akkusativ вместо Dativ: ✗ Ich wasche mich die Hände → **Ich wasche mir die Hände**.","q":[{"k":"mc","s":"Ich freue ___ auf das Wochenende.","o":["mich","mir","sich"],"a":0,"ru":"Я радуюсь предстоящим выходным."},{"k":"mc","s":"Wofür interessierst du ___?","o":["sich","dich","dir"],"a":1,"ru":"Чем ты интересуешься?"},{"k":"mc","s":"Ich putze ___ die Zähne.","o":["mich","sich","mir"],"a":2,"ru":"Я чищу зубы."},{"k":"mc","s":"Kinder, beeilt ___!","o":["sich","uns","dich","euch"],"a":3,"ru":"Дети, поторопитесь!"},{"k":"type","s":"Wir treffen ___ (возвратное местоимение) um acht.","a":["uns"],"ru":"Мы встречаемся в восемь."},{"k":"type","s":"Er erinnert sich gut ___ (предлог) seine Kindheit.","a":["an"],"ru":"Он хорошо помнит своё детство."},{"k":"type","s":"Ziehst du ___ (возвратное местоимение) die Jacke an?","a":["dir"],"ru":"Ты надеваешь куртку?"},{"k":"type","s":"Hast du dich schon ___ (sich vorstellen, Partizip II)?","a":["vorgestellt"],"ru":"Ты уже представился?"},{"k":"order","w":["sich","Anna","für","Musik","interessiert"],"a":["Anna interessiert sich für Musik","Für Musik interessiert sich Anna"],"ru":"Анна интересуется музыкой."},{"k":"order","w":["mich","morgen","ich","melde"],"a":["Ich melde mich morgen","Morgen melde ich mich"],"ru":"Я дам о себе знать завтра."},{"k":"tr","ru":"Я радуюсь подарку.","a":["Ich freue mich über das Geschenk"]},{"k":"tr","ru":"Тебе нужно отдохнуть.","a":["Du musst dich ausruhen","Du musst dich erholen"]}]},{"id":"de-b1-adjektivdeklination","lv":"B1","e":"🎨","t":"Склонение прилагательных","x":"Если прилагательное стоит **после глагола**, у него нет окончания: **Der Film ist gut.** Если **перед существительным** — оно склоняется. Окончание зависит от артикля, рода, числа и падежа.\n\n**1. После определённого артикля** (der, dieser, jeder) — слабое склонение: только **-e** или **-en**.\n\n| | м. р. | ж. р. | ср. р. | мн. ч. |\n| Nom | der gute Film | die gute Idee | das gute Buch | die guten Filme |\n| Akk | den guten Film | die gute Idee | das gute Buch | die guten Filme |\n| Dat | dem guten Film | der guten Idee | dem guten Buch | den guten Filmen |\n\nПравило: **-e** в Nominativ ед. ч. и в Akkusativ ж. и ср. р.; во всех остальных случаях **-en**.\n\n**2. После ein / kein / mein** — смешанное склонение. Там, где у артикля нет окончания, прилагательное «показывает» род: **ein guter Film** (м. р., Nom), **ein gutes Buch** (ср. р., Nom/Akk). Иначе — как после der: **eine gute Idee, einen guten Film, in einem großen Haus, meine guten Freunde**.\n\n**3. Без артикля** — сильное склонение: прилагательное берёт окончание артикля: **guter Wein** (der), **frische Milch** (die), **frisches Brot** (das), **mit kaltem Wasser** (dem). Исключение: Akk м. р. — **schwarzen Kaffee**.\n\n**Типичные ошибки русскоговорящих:**\n- Склоняют прилагательное после глагола: ✗ Das Haus ist großes → **Das Haus ist groß**.\n- Выбирают окончание по смыслу, а не по артиклю: ✗ ein gute Film → **ein guter Film**.\n- Забывают про падеж: ✗ mit dem alte Mann → **mit dem alten Mann**.\n- Пишут одно окончание везде, «на слух». Проверяйте по схеме: артикль → род → падеж.","q":[{"k":"mc","s":"Das ist ein ___ Film.","o":["guter","gute","guten"],"a":0,"ru":"Это хороший фильм."},{"k":"mc","s":"Ich kaufe den ___ Mantel.","o":["rote","roten","roter"],"a":1,"ru":"Я покупаю красное пальто."},{"k":"mc","s":"Sie wohnt in einem ___ Haus.","o":["großes","große","großen"],"a":2,"ru":"Она живёт в большом доме."},{"k":"mc","s":"Ich trinke gern ___ Kaffee.","o":["schwarze","schwarzes","schwarzem","schwarzen"],"a":3,"ru":"Я люблю чёрный кофе."},{"k":"type","s":"Die ___ (neu) Wohnung ist schön.","a":["neue"],"ru":"Новая квартира красивая."},{"k":"type","s":"Wir haben ein ___ (klein) Kind.","a":["kleines"],"ru":"У нас маленький ребёнок."},{"k":"type","s":"Er spricht mit dem ___ (alt) Mann.","a":["alten"],"ru":"Он разговаривает со старым мужчиной."},{"k":"type","s":"Ich mag ___ (frisch) Brot.","a":["frisches"],"ru":"Я люблю свежий хлеб."},{"k":"order","w":["eine","Tasche","habe","neue","ich"],"a":["Ich habe eine neue Tasche","Eine neue Tasche habe ich"],"ru":"У меня новая сумка."},{"k":"order","w":["dem","wohne","in","Haus","weißen","ich"],"a":["Ich wohne in dem weißen Haus","In dem weißen Haus wohne ich"],"ru":"Я живу в (том) белом доме."},{"k":"tr","ru":"Это интересная книга.","a":["Das ist ein interessantes Buch"]},{"k":"tr","ru":"Я помогаю пожилой женщине.","a":["Ich helfe der alten Frau","Ich helfe einer alten Frau","Ich helfe einer älteren Frau","Ich helfe der älteren Frau"]}]},{"id":"de-b1-praeteritum","lv":"B1","e":"📖","t":"Präteritum: прошедшее время в рассказе","x":"**Präteritum** — прошедшее время письменной речи: рассказов, сказок, новостей, биографий. В разговоре чаще используют Perfekt (кроме sein, haben и модальных глаголов).\n\n**Правильные глаголы:** основа + **-te** + окончание. После **-t, -d** — **-ete**.\n\n| | machen | arbeiten | gehen | fahren |\n| ich | machte | arbeitete | ging | fuhr |\n| du | machtest | arbeitetest | gingst | fuhrst |\n| er / sie / es | machte | arbeitete | ging | fuhr |\n| wir | machten | arbeiteten | gingen | fuhren |\n| ihr | machtet | arbeitetet | gingt | fuhrt |\n| sie / Sie | machten | arbeiteten | gingen | fuhren |\n\n**Неправильные глаголы** меняют корень, у **ich** и **er** окончания нет. Формы нужно учить:\n- kommen – **kam**, sehen – **sah**, geben – **gab**, nehmen – **nahm**, sprechen – **sprach**\n- schreiben – **schrieb**, bleiben – **blieb**, finden – **fand**, treffen – **traf**, stehen – **stand**\n\n**Смешанные глаголы** меняют корень и получают **-te**: denken – **dachte**, bringen – **brachte**, wissen – **wusste**, kennen – **kannte**.\n\nОтделяемая приставка уходит в конец, как в Präsens: **Er stand um sechs Uhr auf.**\n\nКлассическое начало сказки: **Es war einmal ein König.** — Жил-был король.\n\n**Типичные ошибки русскоговорящих:**\n- Добавляют **-te** к неправильным глаголам: ✗ gehte, treffte, schreibte → **ging, traf, schrieb**.\n- Добавляют окончание у ich/er: ✗ er ginget, ich kamte → **er ging, ich kam**.\n- Смешивают Präteritum и Perfekt внутри одного рассказа без причины — выбирайте одно время повествования.","q":[{"k":"mc","s":"Gestern ___ ich einen alten Freund.","o":["traf","treffte","trafte"],"a":0,"ru":"Вчера я встретил старого друга."},{"k":"mc","s":"Gestern ___ wir lange auf den Bus.","o":["warten","warteten","wartet"],"a":1,"ru":"Вчера мы долго ждали автобус."},{"k":"mc","s":"Wir saßen beim Essen. Plötzlich ___ das Telefon.","o":["klingt","klingelt","klingelte"],"a":2,"ru":"Мы сидели за едой. Вдруг зазвонил телефон."},{"k":"mc","s":"Letzte Woche ___ er mir einen Brief.","o":["schreibte","schrieben","schreibt","schrieb"],"a":3,"ru":"На прошлой неделе он написал мне письмо."},{"k":"type","s":"Sie ___ (fahren, Präteritum) nach Italien.","a":["fuhr"],"ru":"Она поехала в Италию."},{"k":"type","s":"Ich ___ (denken, Präteritum) an dich.","a":["dachte"],"ru":"Я думал о тебе."},{"k":"type","s":"Ihr ___ (kommen, Präteritum) zu spät.","a":["kamt"],"ru":"Вы (ребята) пришли слишком поздно."},{"k":"type","s":"Um sechs Uhr ___ (aufstehen, Präteritum) er auf.","a":["stand"],"ru":"В шесть часов он встал."},{"k":"order","w":["ging","sie","nach","Hause"],"a":["Sie ging nach Hause","Nach Hause ging sie"],"ru":"Она пошла домой."},{"k":"order","w":["es","einmal","war","König","ein"],"a":["Es war einmal ein König"],"ru":"Жил-был король."},{"k":"tr","ru":"Он не знал ответа. (Präteritum)","a":["Er wusste die Antwort nicht","Er kannte die Antwort nicht"]},{"k":"tr","ru":"Мы долго разговаривали. (Präteritum)","a":["Wir sprachen lange","Wir redeten lange","Wir unterhielten uns lange"]}]},{"id":"de-b1-konjunktiv-2","lv":"B1","e":"💭","t":"Konjunktiv II: желания, советы, нереальные условия","x":"**Konjunktiv II** соответствует русской частице **«бы»**. Он нужен для нереальных условий, желаний, вежливых просьб и советов.\n\n**Формы:**\n- большинство глаголов: **würde + инфинитив**: **Ich würde gern reisen.** — Я бы с удовольствием путешествовал.\n- **sein, haben** и модальные глаголы имеют собственные формы:\n\n| | sein | haben | können | müssen | sollen | werden |\n| ich | wäre | hätte | könnte | müsste | sollte | würde |\n| du | wärst | hättest | könntest | müsstest | solltest | würdest |\n| er / sie | wäre | hätte | könnte | müsste | sollte | würde |\n| wir / sie | wären | hätten | könnten | müssten | sollten | würden |\n\nНекоторые частые глаголы тоже имеют свои формы: **käme** (kommen), **ginge** (gehen), **wüsste** (wissen).\n\n**Употребление:**\n- нереальное условие: **Wenn ich reich wäre, würde ich ein Haus kaufen.** — Если бы я был богат, я бы купил дом.\n- желание: **Wenn ich doch mehr Zeit hätte!**\n- вежливая просьба: **Könnten Sie mir bitte helfen? Ich hätte gern einen Tee.**\n- совет: **Du solltest mehr schlafen. An deiner Stelle würde ich zum Arzt gehen.**\n\nПрошедшее время: **hätte / wäre + Partizip II**: **Wenn ich das gewusst hätte, wäre ich gekommen.**\n\n**Типичные ошибки русскоговорящих:**\n- Путают **konnte** (мог — Präteritum) и **könnte** (мог бы): умлаут меняет смысл!\n- Используют **würde** с sein/haben: ✗ wenn ich reich sein würde — лучше **wenn ich reich wäre**.\n- Ставят Konjunktiv только в одну часть, как «бы» в русском: в немецком он нужен в **обеих** частях: **Wenn ich Zeit hätte, würde ich kommen.**","q":[{"k":"mc","s":"Wenn ich reich ___, würde ich ein Haus kaufen.","o":["wäre","war","würde"],"a":0,"ru":"Если бы я был богат, я бы купил дом."},{"k":"mc","s":"___ Sie mir bitte helfen?","o":["Konnten","Könnten","Mussten"],"a":1,"ru":"Не могли бы Вы мне помочь?"},{"k":"mc","s":"An deiner Stelle ___ ich zum Arzt gehen.","o":["werde","wurde","würde"],"a":2,"ru":"На твоём месте я бы пошёл к врачу."},{"k":"mc","s":"Ich ___ gern einen Tee.","o":["habe","hatte","hätten","hätte"],"a":3,"ru":"Я бы хотел чаю."},{"k":"type","s":"Wenn ich Zeit ___ (haben, Konjunktiv II), käme ich mit.","a":["hätte"],"ru":"Если бы у меня было время, я бы пошёл с вами."},{"k":"type","s":"Du ___ (sollen, Konjunktiv II) mehr schlafen.","a":["solltest"],"ru":"Тебе следовало бы больше спать."},{"k":"type","s":"Was ___ (werden, Konjunktiv II) du an meiner Stelle machen?","a":["würdest"],"ru":"Что бы ты сделал на моём месте?"},{"k":"type","s":"Es ___ (sein, Konjunktiv II) schön, wenn du kommst.","a":["wäre"],"ru":"Было бы здорово, если бы ты пришёл."},{"k":"order","w":["ich","würde","reisen","gern","mehr"],"a":["Ich würde gern mehr reisen","Gern würde ich mehr reisen"],"ru":"Я бы с удовольствием больше путешествовал."},{"k":"order","w":["Sie","das","wiederholen","könnten"],"a":["Könnten Sie das wiederholen"],"ru":"Не могли бы Вы это повторить?"},{"k":"tr","ru":"Если бы у меня была машина, я бы поехал к морю.","a":["Wenn ich ein Auto hätte, würde ich ans Meer fahren","Wenn ich ein Auto hätte, würde ich zum Meer fahren","Wenn ich ein Auto hätte, führe ich ans Meer","Hätte ich ein Auto, würde ich ans Meer fahren","Hätte ich ein Auto, würde ich zum Meer fahren","Ich würde ans Meer fahren, wenn ich ein Auto hätte","Ich würde zum Meer fahren, wenn ich ein Auto hätte"]},{"k":"tr","ru":"Тебе следовало бы больше заниматься спортом.","a":["Du solltest mehr Sport machen","Du solltest mehr Sport treiben"]}]},{"id":"de-b1-relativsaetze","lv":"B1","e":"🔁","t":"Относительные придаточные (Relativsätze)","x":"Относительное придаточное описывает существительное — как русское «который». Оно начинается с **относительного местоимения**, глагол стоит в конце, перед придаточным — запятая: **Das ist der Mann, der neben mir wohnt.**\n\n**Относительные местоимения** почти совпадают с определённым артиклем:\n\n| | м. р. | ж. р. | ср. р. | мн. ч. |\n| Nominativ | der | die | das | die |\n| Akkusativ | den | die | das | die |\n| Dativ | dem | der | dem | **denen** |\n\n**Как выбрать местоимение:**\n- **род и число** — по слову, к которому относится придаточное;\n- **падеж** — по роли в самом придаточном:\n- **Die Frau, die dort steht** (кто стоит? — Nom)\n- **Die Frau, die ich gestern gesehen habe** (кого видел? — Akk)\n- **Die Kinder, denen ich helfe** (кому помогаю? — Dat, мн. ч.)\n\n**С предлогом:** предлог стоит перед местоимением: **das Hotel, in dem wir gewohnt haben**; **der Kollege, mit dem ich arbeite**. О месте можно сказать и **wo**: **die Stadt, wo ich wohne**.\n\nПосле **alles, etwas, nichts, das** используется **was**: **Alles, was er sagt, ist richtig.**\n\n**Типичные ошибки русскоговорящих:**\n- Используют **was** вместо der/die/das, как русское «что» в разговоре: ✗ der Film, was ich gesehen habe → **der Film, den ich gesehen habe**.\n- Берут падеж из главного предложения: ✗ Ich kenne den Mann, den dort steht → **…, der dort steht**.\n- Оставляют глагол на втором месте: ✗ die Frau, die arbeitet in der Bank → **die Frau, die in der Bank arbeitet**.\n- Забывают **denen** в Dativ мн. ч.: ✗ die Kinder, den ich helfe → **denen**.","q":[{"k":"mc","s":"Das ist der Mann, ___ neben mir wohnt.","o":["der","den","dem"],"a":0,"ru":"Это мужчина, который живёт рядом со мной."},{"k":"mc","s":"Die Frau, ___ ich gestern gesehen habe, ist Lehrerin.","o":["der","die","den"],"a":1,"ru":"Женщина, которую я вчера видел, — учительница."},{"k":"mc","s":"Die Kinder, ___ ich helfe, sind nett.","o":["die","der","denen"],"a":2,"ru":"Дети, которым я помогаю, милые."},{"k":"mc","s":"Das ist das Hotel, in ___ wir gewohnt haben.","o":["die","das","den","dem"],"a":3,"ru":"Это гостиница, в которой мы жили."},{"k":"type","s":"Der Film, ___ (который, Akkusativ) wir gesehen haben, war gut.","a":["den"],"ru":"Фильм, который мы посмотрели, был хорошим."},{"k":"type","s":"Ist das das Buch, ___ (которое, Nominativ) dir gefällt?","a":["das"],"ru":"Это та книга, которая тебе нравится?"},{"k":"type","s":"Der Kollege, mit ___ (которым) ich arbeite, ist sehr nett.","a":["dem"],"ru":"Коллега, с которым я работаю, очень милый."},{"k":"type","s":"Alles, ___ (что) er sagt, ist richtig.","a":["was"],"ru":"Всё, что он говорит, правильно."},{"k":"order","w":["ist","Wien","die","Stadt","in","der","ich","wohne"],"a":["Wien ist die Stadt in der ich wohne","Die Stadt in der ich wohne ist Wien"],"ru":"Вена — город, в котором я живу."},{"k":"order","w":["Freund","das","ist","der","mein","aus","Rom","kommt"],"a":["Das ist mein Freund der aus Rom kommt"],"ru":"Это мой друг, который приехал из Рима."},{"k":"tr","ru":"Это женщина, которая работает в банке.","a":["Das ist die Frau, die in der Bank arbeitet","Das ist die Frau, die in einer Bank arbeitet","Das ist die Frau, die bei der Bank arbeitet","Das ist die Frau, die bei einer Bank arbeitet"]},{"k":"tr","ru":"Мне нравится дом, который ты купил.","a":["Mir gefällt das Haus, das du gekauft hast","Das Haus, das du gekauft hast, gefällt mir","Ich mag das Haus, das du gekauft hast"]}]},{"id":"de-b1-infinitiv-mit-zu","lv":"B1","e":"➡️","t":"Инфинитив с zu; um … zu и damit","x":"После многих глаголов и выражений второй глагол стоит в инфинитиве с частицей **zu** в конце предложения: **Ich versuche, pünktlich zu sein.**\n\n**Когда нужен zu:**\n- после глаголов: **versuchen, vergessen, anfangen, beginnen, aufhören, vorhaben, hoffen, planen, bitten**\n- после выражений: **Lust haben, Zeit haben, es ist wichtig / schwer / schön**\n- **Vergiss nicht, mich anzurufen! Ich habe keine Lust, heute zu kochen.**\n\n**Отделяемые глаголы:** **zu** встаёт между приставкой и основой и пишется слитно: anrufen → **anzurufen**, umziehen → **umzuziehen**.\n\n**Без zu:** после модальных глаголов, а также **werden, lassen, gehen, sehen, hören**: **Wir können morgen kommen. Ich gehe schwimmen.**\n\n**Цель: um … zu и damit** — «чтобы».\n\n| Конструкция | Когда | Пример |\n| um … zu + инфинитив | подлежащее одно и то же | Ich lerne Deutsch, um in Deutschland zu studieren. |\n| damit + придаточное | подлежащие разные | Ich spare Geld, damit meine Kinder studieren können. |\n\n**ohne … zu** — «не делая чего-то»: **Sie ging weg, ohne etwas zu sagen.** **statt … zu** — «вместо того чтобы».\n\n**Типичные ошибки русскоговорящих:**\n- Ставят **zu** после модальных глаголов: ✗ Ich kann zu kommen → **Ich kann kommen**.\n- Пишут **zu** отдельно в отделяемых глаголах: ✗ zu anrufen → **anzurufen**.\n- Используют **um … zu** при разных подлежащих: ✗ Ich spare, um meine Kinder zu studieren → **…, damit meine Kinder studieren können**.\n- Переводят «чтобы» как **dass**: ✗ Ich lerne, dass ich… → **um … zu / damit**.","q":[{"k":"mc","s":"Vergiss nicht, mich ___!","o":["anzurufen","zu anrufen","anrufen"],"a":0,"ru":"Не забудь мне позвонить!"},{"k":"mc","s":"Ich habe keine Lust, heute ___ kochen.","o":["um","zu","für"],"a":1,"ru":"У меня нет желания сегодня готовить."},{"k":"mc","s":"Ich lerne Deutsch, ___ in Deutschland zu studieren.","o":["damit","dass","um"],"a":2,"ru":"Я учу немецкий, чтобы учиться в Германии."},{"k":"mc","s":"Ich spare Geld, ___ meine Kinder studieren können.","o":["um","zu","ohne","damit"],"a":3,"ru":"Я коплю деньги, чтобы мои дети могли учиться."},{"k":"type","s":"Es ist wichtig, regelmäßig ___ (üben, с zu).","a":["zu üben"],"ru":"Важно регулярно заниматься."},{"k":"type","s":"Er hat vor, nächstes Jahr ___ (umziehen, с zu).","a":["umzuziehen"],"ru":"Он собирается переехать в следующем году."},{"k":"type","s":"Sie ging weg, ___ (не, «без того чтобы») etwas zu sagen.","a":["ohne"],"ru":"Она ушла, ничего не сказав."},{"k":"type","s":"Wir können morgen ___ (kommen).","a":["kommen"],"ru":"Мы можем прийти завтра."},{"k":"order","w":["versuche","ich","pünktlich","zu","sein"],"a":["Ich versuche pünktlich zu sein","Pünktlich zu sein versuche ich"],"ru":"Я стараюсь быть пунктуальным."},{"k":"order","w":["um","Geld","arbeitet","zu","verdienen","er"],"a":["Er arbeitet um Geld zu verdienen","Um Geld zu verdienen arbeitet er"],"ru":"Он работает, чтобы зарабатывать деньги."},{"k":"tr","ru":"Я начал учить немецкий.","a":["Ich habe angefangen, Deutsch zu lernen","Ich habe begonnen, Deutsch zu lernen","Ich fing an, Deutsch zu lernen","Ich begann, Deutsch zu lernen"]},{"k":"tr","ru":"Я иду в булочную, чтобы купить хлеб.","a":["Ich gehe in die Bäckerei, um Brot zu kaufen","Ich gehe zur Bäckerei, um Brot zu kaufen","Ich gehe zum Bäcker, um Brot zu kaufen"]}]},{"id":"de-b1-temporalsaetze","lv":"B1","e":"⏳","t":"Придаточные времени: als, wenn, bevor, nachdem, während, bis","x":"Временные придаточные отвечают на вопрос «когда?». Как во всех придаточных, глагол стоит **в конце**.\n\n| Союз | Значение | Пример |\n| als | когда (один раз в прошлом) | Als ich ein Kind war, wohnte ich in Kiew. |\n| wenn | когда (повторяется; настоящее/будущее) | Immer wenn es regnet, bleibe ich zu Hause. |\n| bevor | перед тем как | Bevor du gehst, mach das Licht aus. |\n| nachdem | после того как | Nachdem er gegessen hatte, ging er spazieren. |\n| während | пока, в то время как | Während ich koche, deckst du den Tisch. |\n| bis | пока не, до тех пор пока | Warte hier, bis ich zurückkomme. |\n| seit(dem) | с тех пор как | Seit ich in Berlin wohne, spreche ich besser Deutsch. |\n\n**als или wenn?** В прошлом: однократное событие или период → **als**; повторяющееся («каждый раз, когда») → **wenn**. В настоящем и будущем — всегда **wenn**.\n\n**wann** — вопросительное слово, в том числе в косвенном вопросе: **Ich weiß nicht, wann der Zug abfährt.**\n\n**nachdem и Plusquamperfekt.** Действие в придаточном с **nachdem** произошло раньше. Если главное предложение в прошлом, в придаточном — **Plusquamperfekt**: **hatte / war + Partizip II**: **Nachdem wir angekommen waren, riefen wir an.** Если главное в настоящем — в придаточном Perfekt: **Nachdem ich gegessen habe, gehe ich spazieren.**\n\n**Типичные ошибки русскоговорящих:**\n- Переводят «когда» в прошлом как **wenn**: ✗ Wenn ich in Berlin war… (один раз) → **Als ich in Berlin war…**\n- Используют **wann** в придаточном времени: ✗ Wann ich Zeit habe… → **Wenn ich Zeit habe…**\n- Не соблюдают времена с **nachdem**: ✗ Nachdem er aß, ging er → **Nachdem er gegessen hatte, ging er**.","q":[{"k":"mc","s":"___ ich ein Kind war, wohnte ich in Kiew.","o":["Als","Wenn","Wann"],"a":0,"ru":"Когда я был ребёнком, я жил в Киеве."},{"k":"mc","s":"Immer ___ es regnet, bleibe ich zu Hause.","o":["als","wenn","wann"],"a":1,"ru":"Всегда, когда идёт дождь, я остаюсь дома."},{"k":"mc","s":"Nachdem er gegessen ___, ging er spazieren.","o":["war","hat","hatte"],"a":2,"ru":"После того как он поел, он пошёл гулять."},{"k":"mc","s":"Ich weiß nicht, ___ der Zug abfährt.","o":["als","wenn","während","wann"],"a":3,"ru":"Я не знаю, когда отправляется поезд."},{"k":"type","s":"___ (перед тем как) du gehst, mach bitte das Licht aus.","a":["Bevor"],"ru":"Перед тем как уйти, выключи, пожалуйста, свет."},{"k":"type","s":"Nachdem wir angekommen ___ (sein, Plusquamperfekt), riefen wir an.","a":["waren"],"ru":"После того как мы приехали, мы позвонили."},{"k":"type","s":"___ (в то время как) ich koche, deckst du den Tisch.","a":["Während"],"ru":"Пока я готовлю, ты накрываешь на стол."},{"k":"type","s":"Warte hier, ___ (пока не) ich zurückkomme.","a":["bis"],"ru":"Подожди здесь, пока я не вернусь."},{"k":"order","w":["als","ich","ankam","schon","dunkel","es","war"],"a":["Als ich ankam war es schon dunkel","Es war schon dunkel als ich ankam"],"ru":"Когда я приехал, было уже темно."},{"k":"order","w":["wenn","Zeit","habe","ich","lese","ich"],"a":["Wenn ich Zeit habe lese ich","Ich lese wenn ich Zeit habe"],"ru":"Когда у меня есть время, я читаю."},{"k":"tr","ru":"Когда я был в Берлине, я посетил музей.","a":["Als ich in Berlin war, besuchte ich ein Museum","Als ich in Berlin war, habe ich ein Museum besucht","Als ich in Berlin war, besuchte ich das Museum","Als ich in Berlin war, habe ich das Museum besucht","Ich besuchte ein Museum, als ich in Berlin war","Ich habe ein Museum besucht, als ich in Berlin war"]},{"k":"tr","ru":"После того как он закончил работу, он пошёл домой.","a":["Nachdem er die Arbeit beendet hatte, ging er nach Hause","Nachdem er seine Arbeit beendet hatte, ging er nach Hause","Nachdem er mit der Arbeit fertig war, ging er nach Hause","Nachdem er die Arbeit beendet hatte, ist er nach Hause gegangen","Nachdem er seine Arbeit beendet hatte, ist er nach Hause gegangen","Er ging nach Hause, nachdem er die Arbeit beendet hatte"]}]},{"id":"de-b1-passiv","lv":"B1","e":"⚙️","t":"Пассивный залог (Passiv)","x":"Пассив используется, когда важно действие, а не тот, кто его совершает: **Hier wird Deutsch gesprochen.** — Здесь говорят по-немецки. Это частая форма в новостях, инструкциях, официальных текстах.\n\n**Образование:** **werden** (спрягается) + **Partizip II** (в конце).\n\n| Время | Пример |\n| Präsens | Das Haus **wird** renoviert. — Дом ремонтируют. |\n| Präteritum | Das Haus **wurde** 1900 gebaut. — Дом был построен в 1900 году. |\n| Perfekt | Das Auto **ist** repariert **worden**. — Машину отремонтировали. |\n| с модальным глаголом | Die Tür **muss** geschlossen **werden**. — Дверь нужно закрыть. |\n\nФормы **werden**: ich werde, du wirst, er wird, wir werden, ihr werdet, sie werden; Präteritum: **wurde, wurdest, wurde, wurden**.\n\n**Актив → Пассив:** дополнение в Akkusativ становится подлежащим:\n- **Die Kinder malen das Bild.** → **Das Bild wird von den Kindern gemalt.**\n\nИсполнитель указывается через **von + Dativ** (часто его вообще не называют).\n\nБезличный пассив без подлежащего часто начинается с **es** или с обстоятельства: **Hier wird nicht geraucht.**\n\n**Типичные ошибки русскоговорящих:**\n- В Perfekt пишут **geworden**: ✗ ist repariert geworden → **ist repariert worden**.\n- Строят пассив через **sein**, как русское «был построен»: **Das Haus ist gebaut** — это результат (состояние), а процесс — **Das Haus wird gebaut**.\n- Используют **durch** или **bei** вместо **von** для человека: ✗ durch meine Mutter → **von meiner Mutter**.\n- Переводят русские возвратные формы («магазин открывается») пассивом там, где немцы скажут активом: **Der Laden öffnet um 9 Uhr** — тоже правильно.","q":[{"k":"mc","s":"Das Haus ___ gerade renoviert.","o":["wird","hat","werden"],"a":0,"ru":"Дом сейчас ремонтируют."},{"k":"mc","s":"Die Briefe ___ gestern geschickt.","o":["wird","wurden","wurde"],"a":1,"ru":"Письма были отправлены вчера."},{"k":"mc","s":"Das Auto ist repariert ___.","o":["geworden","werden","worden"],"a":2,"ru":"Машину отремонтировали."},{"k":"mc","s":"Der Brief wurde ___ meiner Mutter geschrieben.","o":["durch","mit","bei","von"],"a":3,"ru":"Письмо было написано моей мамой."},{"k":"type","s":"Hier ___ (werden, Präsens) Deutsch gesprochen.","a":["wird"],"ru":"Здесь говорят по-немецки."},{"k":"type","s":"Die Tür muss geschlossen ___ (werden).","a":["werden"],"ru":"Дверь нужно закрыть."},{"k":"type","s":"Das Museum ___ (werden, Präteritum) 1900 gebaut.","a":["wurde"],"ru":"Музей был построен в 1900 году."},{"k":"type","s":"Die Fenster werden jeden Tag ___ (putzen, Partizip II).","a":["geputzt"],"ru":"Окна моют каждый день."},{"k":"order","w":["wird","das","Essen","gekocht"],"a":["Das Essen wird gekocht"],"ru":"Еду готовят."},{"k":"order","w":["von","Kindern","den","gemalt","wurde","Bild","das"],"a":["Das Bild wurde von den Kindern gemalt","Von den Kindern wurde das Bild gemalt"],"ru":"Картина была нарисована детьми."},{"k":"tr","ru":"Магазин открывается в 9 часов. (Passiv)","a":["Der Laden wird um 9 Uhr geöffnet","Das Geschäft wird um 9 Uhr geöffnet","Der Laden wird um neun Uhr geöffnet","Das Geschäft wird um neun Uhr geöffnet","Um 9 Uhr wird der Laden geöffnet","Um 9 Uhr wird das Geschäft geöffnet","Um neun Uhr wird der Laden geöffnet","Um neun Uhr wird das Geschäft geöffnet"]},{"k":"tr","ru":"Эта книга была написана в 1990 году. (Passiv)","a":["Dieses Buch wurde 1990 geschrieben","Das Buch wurde 1990 geschrieben","Dieses Buch wurde im Jahr 1990 geschrieben","Das Buch wurde im Jahr 1990 geschrieben","Dieses Buch ist 1990 geschrieben worden","Das Buch ist 1990 geschrieben worden"]}]},{"id":"de-b2-n-deklination","lv":"B2","e":"🦁","t":"N-Deklination: слабое склонение существительных мужского рода","x":"**N-Deklination** (слабое склонение) — особый тип склонения мужского рода: во всех падежах, кроме именительного единственного числа, существительное получает окончание **-(e)n**.\n\nК ней относятся:\n- существительные мужского рода на **-e**, обозначающие людей и животных: der Junge, der Kollege, der Kunde, der Löwe\n- иностранные слова на **-ent, -ant, -ist, -at, -oge**: der Student, der Praktikant, der Polizist, der Soldat, der Biologe\n- отдельные слова: der Mensch, der Herr, der Nachbar, der Bär, der Patient\n\n| Падеж | Ед. ч. | Мн. ч. |\n| Nom. | der Kollege | die Kollegen |\n| Akk. | den Kollegen | die Kollegen |\n| Dat. | dem Kollegen | den Kollegen |\n| Gen. | des Kollegen | der Kollegen |\n\nПримеры: Ich frage den Nachbarn. — Я спрашиваю соседа. Das Auto des Studenten ist alt. — Машина студента старая. Der Professor hilft dem Studenten. — Профессор помогает студенту.\n\nСлово **Herr** в единственном числе получает **-n** (dem Herrn Müller), во множественном — **-en** (die Herren).\n\nНебольшая группа слов (der Name, der Gedanke, der Buchstabe, der Glaube) в Akk. и Dat. имеет **-n**, а в Genitiv — **-ns**: den Namen, des Namens. Особый случай среднего рода: das Herz — des Herzens, dem Herzen.\n\n**Типичные ошибки русскоязычных:**\n- забывают окончание в Akk. и Dat.: неправильно «Ich sehe den Student», правильно Ich sehe den Studenten;\n- добавляют -s в родительном падеже: неправильно «des Studentens», правильно des Studenten;\n- переносят -n на обычные слова: der Lehrer — den Lehrer, dem Lehrer (без -n!).","q":[{"k":"mc","s":"Ich habe gestern mit dem ___ gesprochen.","o":["Nachbar","Nachbarn","Nachbars"],"a":1,"ru":"Я вчера разговаривал с соседом."},{"k":"mc","s":"Die Meinung des ___ ist uns wichtig.","o":["Kunden","Kunde","Kundens","Kundes"],"a":0,"ru":"Мнение клиента для нас важно."},{"k":"mc","s":"Kennst du den ___ dort am Fenster?","o":["Mensch","Menschens","Menschen"],"a":2,"ru":"Ты знаешь того человека у окна?"},{"k":"mc","s":"Der Chef lobt den neuen ___.","o":["Praktikant","Praktikants","Praktikante","Praktikanten"],"a":3,"ru":"Начальник хвалит нового практиканта."},{"k":"type","s":"Der Arzt untersucht den ___. (Patient)","a":["Patienten"],"ru":"Врач осматривает пациента."},{"k":"type","s":"Wir haben dem ___ Müller eine E-Mail geschrieben. (Herr)","a":["Herrn"],"ru":"Мы написали господину Мюллеру письмо."},{"k":"type","s":"Das Fahrrad des ___ ist kaputt. (Junge)","a":["Jungen"],"ru":"Велосипед мальчика сломан."},{"k":"type","s":"Die Schreibweise des ___ ist kompliziert. (Name)","a":["Namens"],"ru":"Написание этого имени сложное."},{"k":"order","w":["hilft","dem","Studenten","der","Professor"],"a":["Der Professor hilft dem Studenten","Dem Studenten hilft der Professor"],"ru":"Профессор помогает студенту."},{"k":"order","w":["die","Frau","fragt","den","Polizisten","nach","dem","Weg"],"a":["Die Frau fragt den Polizisten nach dem Weg","Den Polizisten fragt die Frau nach dem Weg","Nach dem Weg fragt die Frau den Polizisten"],"ru":"Женщина спрашивает у полицейского дорогу."},{"k":"tr","ru":"Я знаю этого студента.","a":["Ich kenne diesen Studenten","Diesen Studenten kenne ich","Ich kenne den Studenten","Den Studenten kenne ich"]},{"k":"tr","ru":"Мы помогаем нашему соседу.","a":["Wir helfen unserem Nachbarn","Unserem Nachbarn helfen wir"]}]},{"id":"de-b2-zweiteilige-konnektoren","lv":"B2","e":"🔗","t":"Парные союзы: sowohl … als auch, weder … noch, je … desto","x":"**Парные (двойные) союзы** связывают два члена предложения или два предложения.\n\n| Союз | Значение | Пример |\n| sowohl … als auch | и … и | Er spricht sowohl Deutsch als auch Englisch. |\n| weder … noch | ни … ни | Ich habe weder Zeit noch Geld. |\n| entweder … oder | или … или | Entweder du kommst mit, oder du bleibst hier. |\n| nicht nur … sondern auch | не только … но и | Sie ist nicht nur klug, sondern auch nett. |\n| zwar … aber | хотя и … но | Das Hotel ist zwar teuer, aber sehr gut. |\n| je … desto / umso | чем … тем | Je früher wir fahren, desto weniger Stau gibt es. |\n\n**Порядок слов:**\n- **je** вводит придаточное предложение: глагол стоит в конце (Je mehr ich lese, …). После **desto/umso** + сравнительная степень сразу идёт спрягаемый глагол: … desto besser verstehe ich.\n- **zwar** может стоять на первом месте (тогда инверсия: Zwar ist das Hotel teuer, aber …) или в середине предложения.\n- **entweder** допускает оба варианта: Entweder du kommst … / Entweder kommst du …\n- Если **weder … noch** соединяет предложения, после noch — инверсия: Er raucht weder, noch trinkt er.\n\n**Типичные ошибки русскоязычных:**\n- добавляют лишнее отрицание: неправильно «Ich habe weder keine Zeit…» — weder уже содержит отрицание;\n- по аналогии с русским «чем … тем» говорят «je … je» или «je … so» — нужно desto или umso;\n- после desto ставят подлежащее перед глаголом: неправильно «desto besser ich verstehe».","q":[{"k":"mc","s":"Er spricht ___ Englisch als auch Französisch.","o":["sowohl","weder","entweder"],"a":0,"ru":"Он говорит и по-английски, и по-французски."},{"k":"mc","s":"Ich habe ___ Zeit noch Geld.","o":["entweder","weder","zwar"],"a":1,"ru":"У меня нет ни времени, ни денег."},{"k":"mc","s":"Die Wohnung ist ___ teuer, aber sehr schön.","o":["sowohl","weder","zwar"],"a":2,"ru":"Квартира хотя и дорогая, но очень красивая."},{"k":"mc","s":"Je länger ich in Berlin wohne, ___ besser gefällt mir die Stadt.","o":["als","dann","wie","desto"],"a":3,"ru":"Чем дольше я живу в Берлине, тем больше мне нравится город."},{"k":"type","s":"Wir fahren entweder mit dem Zug ___ mit dem Auto. (или … или)","a":["oder"],"ru":"Мы поедем или на поезде, или на машине."},{"k":"type","s":"Sie ist nicht nur intelligent, ___ auch sehr fleißig. (не только … но и)","a":["sondern"],"ru":"Она не только умная, но и очень трудолюбивая."},{"k":"type","s":"Je mehr du übst, ___ schneller lernst du. (чем … тем; не desto)","a":["umso"],"ru":"Чем больше ты тренируешься, тем быстрее учишься."},{"k":"type","s":"Er hat ___ angerufen noch eine E-Mail geschrieben. (ни … ни)","a":["weder"],"ru":"Он не позвонил и не написал письмо."},{"k":"order","w":["zwar","ist","das","Auto","alt","aber","es","fährt","gut"],"a":["Das Auto ist zwar alt aber es fährt gut","Zwar ist das Auto alt aber es fährt gut","Das Auto ist zwar alt es fährt aber gut","Zwar ist das Auto alt es fährt aber gut"],"ru":"Машина хотя и старая, но ездит хорошо."},{"k":"order","w":["je","älter","er","wird","desto","ruhiger","wird","er"],"a":["Je älter er wird desto ruhiger wird er"],"ru":"Чем старше он становится, тем спокойнее."},{"k":"tr","ru":"Я не пью ни кофе, ни чай.","a":["Ich trinke weder Kaffee noch Tee"]},{"k":"tr","ru":"Он говорит и по-немецки, и по-русски.","a":["Er spricht sowohl Deutsch als auch Russisch","Er spricht sowohl Deutsch wie auch Russisch"]}]},{"id":"de-b2-passiv-modal","lv":"B2","e":"🏗️","t":"Пассив во всех временах, с модальными глаголами и Zustandspassiv","x":"**Vorgangspassiv** (пассив действия) образуется с помощью **werden + Partizip II**. Важно само действие, а не тот, кто его выполняет. Исполнитель вводится предлогом **von** + Dat. (лицо) или **durch** + Akk. (средство, причина).\n\n| Время | Пример |\n| Präsens | Das Haus wird gebaut. |\n| Präteritum | Das Haus wurde gebaut. |\n| Perfekt | Das Haus ist gebaut worden. |\n| Plusquamperfekt | Das Haus war gebaut worden. |\n| Futur I | Das Haus wird gebaut werden. |\n\nВ Perfekt и Plusquamperfekt используется форма **worden** (без ge-!), вспомогательный глагол — всегда **sein**.\n\n**Пассив с модальными глаголами:** модальный глагол + Partizip II + **werden**:\n- Das Auto muss repariert werden. — Машину нужно отремонтировать.\n- Das Auto musste repariert werden. — Машину нужно было отремонтировать.\n- Ich weiß, dass das Auto repariert werden muss. — в придаточном модальный глагол стоит в самом конце.\n\n**Zustandspassiv** (пассив состояния) = **sein + Partizip II**. Он описывает результат действия: Die Tür wird geöffnet. — Дверь открывают. Die Tür ist geöffnet. — Дверь открыта.\n\nПример: Das Buch ist von vielen Menschen gelesen worden. — Эту книгу прочитали многие люди.\n\n**Типичные ошибки русскоязычных:**\n- неправильно «ist gebaut geworden», правильно ist gebaut worden;\n- путают Vorgangspassiv и Zustandspassiv: русское «дверь открыта» — это состояние, значит sein, а не werden;\n- в Perfekt берут haben: неправильно «hat gebaut worden», возможно только ist … worden.","q":[{"k":"mc","s":"Das Haus ist 1990 gebaut ___.","o":["geworden","worden","werden"],"a":1,"ru":"Дом был построен в 1990 году."},{"k":"mc","s":"Der Brief muss heute noch ___ werden.","o":["geschrieben","schreiben","geschreibt"],"a":0,"ru":"Письмо нужно написать ещё сегодня."},{"k":"mc","s":"Keine Sorge, das Problem ___ jetzt gelöst. (состояние)","o":["wird","wurde","ist","hat"],"a":2,"ru":"Не волнуйся, проблема теперь решена."},{"k":"mc","s":"Ich weiß, dass das Fenster repariert werden ___.","o":["sollen","hat","ist","muss"],"a":3,"ru":"Я знаю, что окно нужно отремонтировать."},{"k":"type","s":"Die Brücke ___ letztes Jahr gebaut. (werden, Präteritum)","a":["wurde"],"ru":"Мост построили в прошлом году."},{"k":"type","s":"Das Paket ist gestern ___ worden. (schicken)","a":["geschickt"],"ru":"Посылку отправили вчера."},{"k":"type","s":"Die Rechnung ___ bis Freitag bezahlt werden. (müssen, Präsens)","a":["muss"],"ru":"Счёт нужно оплатить до пятницы."},{"k":"type","s":"Als wir ankamen, ___ die Fenster schon geputzt worden. (sein, Plusquamperfekt Passiv)","a":["waren"],"ru":"Когда мы приехали, окна уже были вымыты."},{"k":"order","w":["das","Auto","muss","morgen","repariert","werden"],"a":["Das Auto muss morgen repariert werden","Morgen muss das Auto repariert werden"],"ru":"Машину нужно отремонтировать завтра."},{"k":"order","w":["das","Buch","ist","von","vielen","Menschen","gelesen","worden"],"a":["Das Buch ist von vielen Menschen gelesen worden","Von vielen Menschen ist das Buch gelesen worden"],"ru":"Книгу прочитали многие люди."},{"k":"tr","ru":"Музей был построен в 1900 году.","a":["Das Museum wurde 1900 gebaut","Das Museum wurde im Jahr 1900 gebaut","Das Museum ist 1900 gebaut worden","Das Museum ist im Jahr 1900 gebaut worden","1900 wurde das Museum gebaut","Im Jahr 1900 wurde das Museum gebaut","1900 ist das Museum gebaut worden","Im Jahr 1900 ist das Museum gebaut worden","Das Museum wurde 1900 erbaut","1900 wurde das Museum erbaut"]},{"k":"tr","ru":"Эту проблему нужно решить.","a":["Dieses Problem muss gelöst werden","Das Problem muss gelöst werden","Dieses Problem ist zu lösen","Das Problem ist zu lösen","Man muss dieses Problem lösen","Man muss das Problem lösen"]}]},{"id":"de-b2-passiv-ersatz","lv":"B2","e":"🔄","t":"Заменители пассива: sein + zu, sich lassen, -bar","x":"Немецкий язык часто заменяет пассив другими конструкциями. Они звучат короче и встречаются в инструкциях, объявлениях и газетах.\n\n- **man + актив**: Man repariert das Auto. = Das Auto wird repariert.\n- **sein + zu + Infinitiv** = пассив с können или müssen/sollen: Die Rechnung ist sofort zu bezahlen. — Счёт нужно оплатить немедленно. Das Problem ist leicht zu lösen. — Проблему легко решить.\n- **sich lassen + Infinitiv** = пассив с können: Das Fenster lässt sich nicht öffnen. — Окно невозможно открыть.\n- **прилагательные на -bar / -lich** = kann … werden: Das Wasser ist trinkbar. — Воду можно пить. Die Schrift ist unleserlich. — Почерк невозможно прочитать.\n\nУ отделяемых глаголов zu встаёт между приставкой и корнем: Die Formulare sind bis Montag auszufüllen. — Бланки нужно заполнить до понедельника.\n\n| Пассив / man | Замена |\n| Das kann man nicht ändern. | Das lässt sich nicht ändern. |\n| Der Text muss übersetzt werden. | Der Text ist zu übersetzen. |\n| Das kann man nicht lesen. | Das ist nicht lesbar. |\n\nЗначение sein + zu определяется контекстом: «нужно» — в правилах и требованиях, «можно» — обычно с наречиями leicht, schwer, kaum, nicht.\n\n**Типичные ошибки русскоязычных:**\n- после lassen ставят Partizip II: неправильно «lässt sich gelöst», правильно lässt sich lösen;\n- в конструкцию sein + zu добавляют werden: неправильно «ist zu bezahlen werden»;\n- забывают возвратное sich: неправильно «Das Problem lässt leicht lösen».","q":[{"k":"mc","s":"Das Problem lässt sich leicht ___.","o":["lösen","gelöst","zu lösen"],"a":0,"ru":"Эту проблему легко решить."},{"k":"mc","s":"Die Formulare sind bis Montag ___.","o":["ausfüllen","auszufüllen","ausgefüllt werden"],"a":1,"ru":"Бланки нужно заполнить до понедельника."},{"k":"mc","s":"Diese Handschrift ist kaum ___. (= kann kaum gelesen werden)","o":["lesend","lesen","lesbar"],"a":2,"ru":"Этот почерк почти невозможно прочитать."},{"k":"mc","s":"Der Fehler ___ sich nicht mehr korrigieren.","o":["ist","wird","hat","lässt"],"a":3,"ru":"Ошибку уже невозможно исправить."},{"k":"type","s":"Der Antrag ist bis Freitag ___. (einreichen, sein + zu)","a":["einzureichen"],"ru":"Заявление нужно подать до пятницы."},{"k":"type","s":"Das Fenster ___ sich nicht öffnen. (lassen)","a":["lässt"],"ru":"Окно не открывается."},{"k":"type","s":"Das Wasser ist nicht ___. (= kann nicht getrunken werden; прилагательное на -bar)","a":["trinkbar"],"ru":"Эту воду нельзя пить."},{"k":"type","s":"Diese Fragen ___ nicht leicht zu beantworten. (sein)","a":["sind"],"ru":"На эти вопросы нелегко ответить."},{"k":"order","w":["das","lässt","sich","nicht","ändern"],"a":["Das lässt sich nicht ändern"],"ru":"Этого не изменить."},{"k":"order","w":["die","Rechnung","ist","sofort","zu","bezahlen"],"a":["Die Rechnung ist sofort zu bezahlen","Sofort ist die Rechnung zu bezahlen"],"ru":"Счёт нужно оплатить немедленно."},{"k":"tr","ru":"Этот текст легко перевести.","a":["Der Text lässt sich leicht übersetzen","Der Text ist leicht zu übersetzen","Der Text ist leicht übersetzbar","Der Text kann leicht übersetzt werden","Dieser Text lässt sich leicht übersetzen","Dieser Text ist leicht zu übersetzen","Dieser Text ist leicht übersetzbar","Dieser Text kann leicht übersetzt werden","Man kann den Text leicht übersetzen","Man kann diesen Text leicht übersetzen"]},{"k":"tr","ru":"Здесь нельзя курить.","a":["Hier darf man nicht rauchen","Man darf hier nicht rauchen","Hier darf nicht geraucht werden","Hier ist Rauchen verboten","Hier ist das Rauchen verboten","Rauchen ist hier verboten","Das Rauchen ist hier verboten"]}]},{"id":"de-b2-konjunktiv-ii-vergangenheit","lv":"B2","e":"⏪","t":"Konjunktiv II прошедшего времени: hätte/wäre + Partizip II","x":"**Konjunktiv II прошедшего времени** выражает нереальное условие, желание или упрёк в прошлом — то, что могло бы произойти, но не произошло.\n\nОбразование: **hätte / wäre + Partizip II**. Выбор hätte или wäre — как в Perfekt: ich habe gearbeitet → ich hätte gearbeitet; ich bin gefahren → ich wäre gefahren.\n\n| Лицо | haben | sein |\n| ich | hätte gesehen | wäre gekommen |\n| du | hättest gesehen | wärst gekommen |\n| er/sie/es | hätte gesehen | wäre gekommen |\n| wir/sie/Sie | hätten gesehen | wären gekommen |\n\nПримеры:\n- Wenn ich das gewusst hätte, wäre ich gekommen. — Если бы я это знал, я бы пришёл.\n- Hätte ich das gewusst, wäre ich gekommen. — то же без wenn (глагол на первом месте).\n- Wenn ich doch mehr gelernt hätte! — Если бы я больше учился!\n- Ohne deine Hilfe hätte ich es nicht geschafft. — Без твоей помощи я бы не справился.\n\n**С модальными глаголами** используется двойной инфинитив: hätte + Infinitiv + модальный глагол в инфинитиве.\n- Du hättest mich anrufen sollen. — Тебе следовало мне позвонить.\n- Wir hätten früher losfahren müssen. — Нам нужно было выехать раньше.\nВ придаточном предложении hätte стоит перед двойным инфинитивом: …, dass er hätte kommen sollen.\n\n**Типичные ошибки русскоязычных:**\n- используют würde + Partizip II: неправильно «Ich würde das gemacht», правильно Ich hätte das gemacht;\n- выбирают hätte у глаголов движения: неправильно «hätte gefahren», правильно wäre gefahren;\n- после модального глагола ставят Partizip II: неправильно «hätte kommen gesollt», правильно hätte kommen sollen.","q":[{"k":"mc","s":"Wenn ich früher aufgestanden ___, hätte ich den Bus nicht verpasst.","o":["hätte","wäre","würde"],"a":1,"ru":"Если бы я встал раньше, я бы не опоздал на автобус."},{"k":"mc","s":"Du ___ mich anrufen sollen!","o":["hättest","wärst","würdest"],"a":0,"ru":"Тебе следовало мне позвонить!"},{"k":"mc","s":"Ohne deine Hilfe ___ ich die Prüfung nicht bestanden.","o":["wäre","würde","hätte"],"a":2,"ru":"Без твоей помощи я бы не сдал экзамен."},{"k":"mc","s":"Ich weiß, dass er früher ___ kommen sollen.","o":["wäre","würde","hat","hätte"],"a":3,"ru":"Я знаю, что ему следовало прийти раньше."},{"k":"type","s":"Wenn wir mehr Zeit gehabt ___, wären wir länger geblieben. (haben)","a":["hätten"],"ru":"Если бы у нас было больше времени, мы бы остались дольше."},{"k":"type","s":"Wenn sie mit dem Taxi gefahren ___, wäre sie pünktlich gewesen. (sein)","a":["wäre"],"ru":"Если бы она поехала на такси, она была бы вовремя."},{"k":"type","s":"Ich hätte das nicht ___ sollen. (sagen)","a":["sagen"],"ru":"Мне не следовало этого говорить."},{"k":"type","s":"An deiner Stelle ___ ich das Angebot angenommen. (haben)","a":["hätte"],"ru":"На твоём месте я бы принял это предложение."},{"k":"order","w":["wenn","ich","das","gewusst","hätte","wäre","ich","gekommen"],"a":["Wenn ich das gewusst hätte wäre ich gekommen","Ich wäre gekommen wenn ich das gewusst hätte"],"ru":"Если бы я это знал, я бы пришёл."},{"k":"order","w":["wir","hätten","früher","losfahren","müssen"],"a":["Wir hätten früher losfahren müssen","Früher hätten wir losfahren müssen"],"ru":"Нам нужно было выехать раньше."},{"k":"tr","ru":"Тебе следовало прийти раньше. (упрёк о прошлом)","a":["Du hättest früher kommen sollen","Du hättest eher kommen sollen"]},{"k":"tr","ru":"Мы бы остались дольше. (о прошлом)","a":["Wir wären länger geblieben"]}]},{"id":"de-b2-infinitivkonstruktionen","lv":"B2","e":"🎯","t":"Инфинитивные обороты: um/ohne/statt … zu и инфинитив перфекта","x":"Инфинитивные обороты с **zu** заменяют придаточные предложения, если **подлежащее в обеих частях одно и то же**.\n\n| Оборот | Значение | При разных подлежащих |\n| um … zu | чтобы | damit |\n| ohne … zu | не делая (чего-то) | ohne dass |\n| (an)statt … zu | вместо того чтобы | (an)statt dass |\n\n- Ich lerne Deutsch, um in Wien zu studieren. — Я учу немецкий, чтобы учиться в Вене.\n- Ich spreche langsam, damit alle mich verstehen. — Я говорю медленно, чтобы все меня понимали (подлежащие разные → damit).\n- Er ging, ohne sich zu verabschieden. — Он ушёл, не попрощавшись.\n- Wir gingen, ohne dass der Chef es merkte. — Мы ушли, и начальник этого не заметил.\n- Statt zu lernen, spielte er. — Вместо того чтобы учиться, он играл.\n\nУ отделяемых глаголов zu ставится между приставкой и корнем: anzurufen, abzuschließen.\n\n**Инфинитив перфекта** (Partizip II + zu + haben/sein) показывает, что действие уже произошло:\n- Ich bin froh, die Prüfung bestanden zu haben. — Я рад, что сдал экзамен.\n- Er behauptet, pünktlich angekommen zu sein. — Он утверждает, что пришёл вовремя.\n\nОборот может стоять перед главным предложением, тогда в главном предложении инверсия: Um Geld zu sparen, fährt sie mit dem Rad. — Чтобы сэкономить, она ездит на велосипеде.\n\n**Типичные ошибки русскоязычных:**\n- употребляют um … zu при разных подлежащих: неправильно «Ich spreche langsam, um alle mich zu verstehen», нужно damit;\n- ставят zu перед отделяемой приставкой: неправильно «zu anrufen», правильно anzurufen;\n- забывают zu: неправильно «ohne sich verabschieden».","q":[{"k":"mc","s":"Er ging einfach, ___ sich zu verabschieden. (не попрощавшись)","o":["ohne","um","damit"],"a":0,"ru":"Он просто ушёл, не попрощавшись."},{"k":"mc","s":"Ich spreche langsam, ___ alle mich verstehen.","o":["um","damit","ohne"],"a":1,"ru":"Я говорю медленно, чтобы все меня понимали."},{"k":"mc","s":"___ für die Prüfung zu lernen, hat er Computerspiele gespielt. (вместо того чтобы)","o":["Um","Ohne","Statt"],"a":2,"ru":"Вместо того чтобы готовиться к экзамену, он играл в компьютерные игры."},{"k":"mc","s":"Ich freue mich, Sie kennengelernt zu ___.","o":["sein","werden","worden","haben"],"a":3,"ru":"Я рад, что познакомился с Вами."},{"k":"type","s":"Sie spart Geld, ___ ein Auto zu kaufen. (чтобы)","a":["um"],"ru":"Она копит деньги, чтобы купить машину."},{"k":"type","s":"Er ist froh, pünktlich angekommen zu ___. (Infinitiv Perfekt)","a":["sein"],"ru":"Он рад, что приехал вовремя."},{"k":"type","s":"Wir sind gegangen, ohne dass der Chef es ___. (merken, Präteritum)","a":["merkte"],"ru":"Мы ушли так, что начальник этого не заметил."},{"k":"type","s":"Er hat vergessen, die Tür ___. (abschließen, Infinitiv mit zu)","a":["abzuschließen"],"ru":"Он забыл запереть дверь."},{"k":"order","w":["ich","lerne","Deutsch","um","in","Wien","zu","studieren"],"a":["Ich lerne Deutsch um in Wien zu studieren","Um in Wien zu studieren lerne ich Deutsch"],"ru":"Я учу немецкий, чтобы учиться в Вене."},{"k":"order","w":["er","verließ","den","Raum","ohne","ein","Wort","zu","sagen"],"a":["Er verließ den Raum ohne ein Wort zu sagen","Ohne ein Wort zu sagen verließ er den Raum"],"ru":"Он вышел из комнаты, не сказав ни слова."},{"k":"tr","ru":"Она ушла, не попрощавшись.","a":["Sie ist gegangen, ohne sich zu verabschieden","Sie ging, ohne sich zu verabschieden","Sie ging weg, ohne sich zu verabschieden","Sie ist weggegangen, ohne sich zu verabschieden"]},{"k":"tr","ru":"Я рад, что увидел тебя. (инфинитив перфекта)","a":["Ich bin froh, dich gesehen zu haben","Ich freue mich, dich gesehen zu haben"]}]},{"id":"de-b2-genitiv-praepositionen","lv":"B2","e":"⚖️","t":"Предлоги с Genitiv: wegen, trotz, während, innerhalb","x":"Ряд предлогов требует **родительного падежа (Genitiv)**. Они особенно частотны в письменной и официальной речи.\n\n| Предлог | Значение | Пример |\n| wegen | из-за | wegen des Regens |\n| trotz | несмотря на | trotz der Kälte |\n| während | во время | während des Urlaubs |\n| (an)statt | вместо | statt eines Briefes |\n| innerhalb | в течение, внутри | innerhalb einer Woche |\n| außerhalb | вне, за пределами | außerhalb der Stadt |\n| aufgrund | на основании, из-за | aufgrund der hohen Kosten |\n\nОкончания Genitiv: мужской и средний род — **des / eines**, существительное получает **-(e)s** (des Regens, eines Staus); женский род и множественное число — **der** (der Stadt, der Kosten). Прилагательное после артикля получает **-en**: wegen des schlechten Wetters.\n\nПримеры:\n- Wegen des Streiks fiel der Unterricht aus. — Из-за забастовки занятия отменили.\n- Trotz des Regens gingen wir spazieren. — Несмотря на дождь, мы пошли гулять.\n- Sie arbeitet während der Ferien in einem Café. — Во время каникул она работает в кафе.\n\nВ разговорной речи после wegen, trotz и während часто звучит дательный падеж (wegen dem Wetter), но в письменной речи и на экзамене нужен Genitiv.\n\n**Типичные ошибки русскоязычных:**\n- переносят русское управление: неправильно «trotz den Regen», «wegen die Krankheit», правильно trotz des Regens, wegen der Krankheit;\n- забывают -s у существительного: неправильно «während des Urlaub», правильно während des Urlaubs;\n- путают während (во время) и innerhalb (в пределах срока).","q":[{"k":"mc","s":"___ des schlechten Wetters fand das Spiel statt.","o":["Trotz","Wegen","Während"],"a":0,"ru":"Несмотря на плохую погоду, игра состоялась."},{"k":"mc","s":"Wir müssen die Arbeit ___ einer Woche abgeben. (в пределах срока)","o":["während","innerhalb","trotz"],"a":1,"ru":"Мы должны сдать работу в течение недели."},{"k":"mc","s":"Wegen ___ Krankheit konnte sie nicht kommen.","o":["ihre","ihrem","ihrer"],"a":2,"ru":"Из-за болезни она не смогла прийти."},{"k":"mc","s":"Während ___ Urlaubs habe ich viel gelesen.","o":["der","dem","den","des"],"a":3,"ru":"Во время отпуска я много читал."},{"k":"type","s":"Trotz ___ Regens gingen wir spazieren. (der)","a":["des"],"ru":"Несмотря на дождь, мы пошли гулять."},{"k":"type","s":"Wegen ___ Staus kamen wir zu spät. (ein)","a":["eines"],"ru":"Из-за пробки мы опоздали."},{"k":"type","s":"Er wohnt außerhalb ___ Stadt. (die)","a":["der"],"ru":"Он живёт за городом."},{"k":"type","s":"Aufgrund ___ hohen Kosten wurde das Projekt gestoppt. (die, Plural)","a":["der"],"ru":"Из-за высоких затрат проект остановили."},{"k":"order","w":["wegen","des","Streiks","fiel","der","Unterricht","aus"],"a":["Wegen des Streiks fiel der Unterricht aus","Der Unterricht fiel wegen des Streiks aus"],"ru":"Из-за забастовки занятия отменили."},{"k":"order","w":["während","der","Ferien","arbeitet","sie","in","einem","Café"],"a":["Während der Ferien arbeitet sie in einem Café","Sie arbeitet während der Ferien in einem Café","In einem Café arbeitet sie während der Ferien","Sie arbeitet in einem Café während der Ferien"],"ru":"Во время каникул она работает в кафе."},{"k":"tr","ru":"Несмотря на дождь, мы поехали на море.","a":["Trotz des Regens sind wir ans Meer gefahren","Trotz des Regens fuhren wir ans Meer","Wir sind trotz des Regens ans Meer gefahren","Wir fuhren trotz des Regens ans Meer"]},{"k":"tr","ru":"Из-за болезни он не пришёл.","a":["Wegen der Krankheit ist er nicht gekommen","Wegen der Krankheit kam er nicht","Wegen seiner Krankheit ist er nicht gekommen","Wegen seiner Krankheit kam er nicht","Aufgrund der Krankheit ist er nicht gekommen","Aufgrund der Krankheit kam er nicht","Aufgrund seiner Krankheit ist er nicht gekommen","Aufgrund seiner Krankheit kam er nicht","Er ist wegen der Krankheit nicht gekommen","Er ist wegen seiner Krankheit nicht gekommen","Er ist aufgrund der Krankheit nicht gekommen","Er ist aufgrund seiner Krankheit nicht gekommen","Er kam wegen der Krankheit nicht","Er kam wegen seiner Krankheit nicht","Er kam aufgrund der Krankheit nicht","Er kam aufgrund seiner Krankheit nicht"]}]},{"id":"de-c1-indirekte-rede","lv":"C1","e":"🗞️","t":"Konjunktiv I и косвенная речь","x":"В косвенной речи немецкий язык использует **Konjunktiv I**. Так автор показывает, что передаёт чужие слова и не отвечает за их достоверность.\n\n**Образование:** основа инфинитива + окончания -e, -est, -e, -en, -et, -en. Чаще всего нужно 3-е лицо ед. ч.: er komme, er habe, er könne, er werde. Особый глагол — **sein**: ich sei, du seist, er sei, wir seien, sie seien.\n\n| Время | Прямая речь | Косвенная речь |\n| настоящее | «Ich bin krank.» | Er sagt, er sei krank. |\n| прошедшее | «Ich habe nichts gesehen.» | Er sagt, er habe nichts gesehen. |\n| будущее | «Ich werde kommen.» | Er sagt, er werde kommen. |\n\nДля всех прошедших времён есть одна форма: **habe / sei + Partizip II**\n\n**Замена на Konjunktiv II:** если форма Konjunktiv I совпадает с индикативом (чаще всего во множественном числе и в 1-м лице), берут Konjunktiv II: sie haben → sie **hätten**, wir sollen → wir **sollten**, ich komme → ich **käme** / ich würde kommen.\n\n**Вопросы** передаются через **ob** или вопросительное слово: Er fragte, ob ich Zeit hätte. **Просьбы и приказы** — через sollen или mögen: Sie sagte, ich solle warten.\n\nСоюз dass можно опустить, тогда порядок слов прямой: Er sagt, er sei krank. = Er sagt, dass er krank sei. — Он говорит, что болен.\n\n**Типичные ошибки русскоязычных:**\n- оставляют индикатив: «Er sagte, er ist krank» — в устной речи допустимо, в письменной нужен Konjunktiv;\n- употребляют форму Konjunktiv I, совпадающую с индикативом: «sie haben» вместо sie hätten;\n- не меняют местоимения: «Ich bin müde», sagt er → Er sagt, er sei müde (а не ich sei müde).","q":[{"k":"mc","s":"Der Minister sagte, er ___ keine Zeit.","o":["habe","hat","hätte gehabt"],"a":0,"ru":"Министр сказал, что у него нет времени."},{"k":"mc","s":"Sie erklärte, sie ___ gestern krank gewesen.","o":["habe","sei","werde"],"a":1,"ru":"Она объяснила, что вчера была больна."},{"k":"mc","s":"Die Zeugen sagten, sie ___ nichts gesehen. (Ersatzform)","o":["haben","habe","hätten"],"a":2,"ru":"Свидетели сказали, что ничего не видели."},{"k":"mc","s":"Er fragte, ___ ich morgen Zeit hätte.","o":["dass","wenn","was","ob"],"a":3,"ru":"Он спросил, будет ли у меня завтра время."},{"k":"type","s":"Laut Polizei ___ der Fahrer zu schnell gefahren. (sein, Konjunktiv I)","a":["sei"],"ru":"По данным полиции, водитель ехал слишком быстро."},{"k":"type","s":"Sie sagt, sie ___ morgen nach Berlin. (fahren, Konjunktiv I)","a":["fahre"],"ru":"Она говорит, что завтра поедет в Берлин."},{"k":"type","s":"Der Chef sagte, wir ___ pünktlich sein. (sollen, Ersatzform Konjunktiv II)","a":["sollten"],"ru":"Начальник сказал, что мы должны быть пунктуальны."},{"k":"type","s":"Er behauptet, er ___ das Geld zurückgeben. (werden, Konjunktiv I)","a":["werde"],"ru":"Он утверждает, что вернёт деньги."},{"k":"order","w":["sie","sagte","sie","habe","keine","Lust"],"a":["Sie sagte sie habe keine Lust","Sie habe keine Lust sagte sie"],"ru":"Она сказала, что у неё нет желания."},{"k":"order","w":["er","behauptet","dass","er","nichts","gewusst","habe"],"a":["Er behauptet dass er nichts gewusst habe","Dass er nichts gewusst habe behauptet er"],"ru":"Он утверждает, что ничего не знал."},{"k":"tr","ru":"Он сказал, что он болен. (Konjunktiv I)","a":["Er sagte, er sei krank","Er sagte, dass er krank sei","Er hat gesagt, er sei krank","Er hat gesagt, dass er krank sei"]},{"k":"tr","ru":"Она спросила, приду ли я.","a":["Sie fragte, ob ich käme","Sie fragte, ob ich kommen würde","Sie fragte, ob ich komme","Sie fragte, ob ich kommen werde","Sie hat gefragt, ob ich käme","Sie hat gefragt, ob ich kommen würde","Sie hat gefragt, ob ich komme","Sie hat gefragt, ob ich kommen werde"]}]},{"id":"de-c1-partizipialattribute","lv":"C1","e":"🧩","t":"Партиципиальные определения (Partizip I, Partizip II, zu + Partizip I)","x":"**Партиципиальное определение** — это причастие перед существительным, которое склоняется как прилагательное. Оно заменяет относительное придаточное и характерно для письменного, научного и газетного стиля.\n\n- **Partizip I** (инфинитив + -d) — активное, одновременное действие: das schlafende Kind = das Kind, das schläft (спящий ребёнок).\n- **Partizip II** — пассивное или завершённое действие: das reparierte Auto = das Auto, das repariert wurde (отремонтированный автомобиль); der angekommene Zug = der Zug, der angekommen ist (прибывший поезд).\n- **zu + Partizip I** (Gerundiv) — необходимость или возможность: die zu lösende Aufgabe = die Aufgabe, die gelöst werden muss (задача, которую нужно решить). У отделяемых глаголов: die abzuholenden Pakete.\n\n**Расширенное определение:** все зависимые слова стоят между артиклем и причастием, а причастие — непосредственно перед существительным:\n- der seit Jahren in Berlin lebende Künstler — художник, который уже много лет живёт в Берлине;\n- die im letzten Jahr gebaute Brücke — мост, построенный в прошлом году.\n\n| Относительное предложение | Партиципиальное определение |\n| der Preis, der schnell steigt | der schnell steigende Preis |\n| der Roman, den die Lehrerin empfohlen hat | der von der Lehrerin empfohlene Roman |\n| die Rechnungen, die bezahlt werden müssen | die zu bezahlenden Rechnungen |\n\nЧитая длинное определение, найдите сначала артикль и существительное, а потом всё, что стоит между ними.\n\n**Типичные ошибки русскоязычных:**\n- ставят определение после существительного, как в русском обороте: неправильно «die Brücke gebaute im letzten Jahr»;\n- забывают окончание: неправильно «das schlafend Kind»;\n- смешивают формы: неправильно «die geschriebenden Briefe», правильно die geschriebenen Briefe.","q":[{"k":"mc","s":"Das ___ Kind darf man nicht wecken.","o":["schlafende","geschlafene","schlafenden"],"a":0,"ru":"Спящего ребёнка нельзя будить."},{"k":"mc","s":"Die schon ___ Briefe liegen auf dem Tisch.","o":["schreibenden","geschriebenen","geschrieben"],"a":1,"ru":"Уже написанные письма лежат на столе."},{"k":"mc","s":"Die bis morgen zu ___ Aufgaben sind schwer.","o":["lösen","gelöste","lösenden"],"a":2,"ru":"Задачи, которые нужно решить до завтра, трудные."},{"k":"mc","s":"Der seit Jahren in Berlin ___ Künstler stellt im Museum aus.","o":["gelebte","lebenden","gelebten","lebende"],"a":3,"ru":"Художник, много лет живущий в Берлине, выставляется в музее."},{"k":"type","s":"Wir sahen den ___ Zug. (abfahren, Partizip I)","a":["abfahrenden"],"ru":"Мы видели отъезжающий поезд."},{"k":"type","s":"Das gestern ___ Auto fährt wieder gut. (reparieren, Partizip II)","a":["reparierte"],"ru":"Отремонтированная вчера машина снова хорошо ездит."},{"k":"type","s":"Die zu ___ Rechnungen liegen im Ordner. (bezahlen)","a":["bezahlenden"],"ru":"Счета, которые нужно оплатить, лежат в папке."},{"k":"type","s":"Mit dem schnell ___ Preis waren alle unzufrieden. (steigen, Partizip I)","a":["steigenden"],"ru":"Все были недовольны быстро растущей ценой."},{"k":"order","w":["die","im","letzten","Jahr","gebaute","Brücke","ist","schon","kaputt"],"a":["Die im letzten Jahr gebaute Brücke ist schon kaputt"],"ru":"Мост, построенный в прошлом году, уже сломан."},{"k":"order","w":["wir","lesen","den","von","der","Lehrerin","empfohlenen","Roman"],"a":["Wir lesen den von der Lehrerin empfohlenen Roman","Den von der Lehrerin empfohlenen Roman lesen wir"],"ru":"Мы читаем роман, рекомендованный учительницей."},{"k":"tr","ru":"Плачущий ребёнок ищет свою маму.","a":["Das weinende Kind sucht seine Mutter","Das weinende Kind sucht seine Mama","Das weinende Kind sucht nach seiner Mutter","Das weinende Kind sucht nach seiner Mama"]},{"k":"tr","ru":"Мы обсудили опубликованную вчера статью.","a":["Wir haben den gestern veröffentlichten Artikel besprochen","Wir haben den gestern veröffentlichten Artikel diskutiert","Wir haben den gestern publizierten Artikel besprochen","Wir haben den gestern publizierten Artikel diskutiert","Wir besprachen den gestern veröffentlichten Artikel","Wir besprachen den gestern publizierten Artikel","Wir diskutierten den gestern veröffentlichten Artikel","Wir diskutierten den gestern publizierten Artikel","Den gestern veröffentlichten Artikel haben wir besprochen","Den gestern veröffentlichten Artikel haben wir diskutiert","Den gestern publizierten Artikel haben wir besprochen","Den gestern publizierten Artikel haben wir diskutiert"]}]},{"id":"de-c1-nominalstil","lv":"C1","e":"🏛️","t":"Номинализация и номинальный стиль","x":"**Номинальный стиль** — употребление существительных вместо глаголов и придаточных предложений. Он типичен для деловых текстов, науки, СМИ и экзамена уровня C1.\n\n**Как образуется существительное от глагола:**\n- суффикс **-ung** (ж. р.): lösen → die Lösung, eröffnen → die Eröffnung\n- субстантивированный инфинитив (ср. р.): lesen → das Lesen\n- основа глагола (часто м. р.): besuchen → der Besuch, anfangen → der Anfang\n- другие формы: abreisen → die Abreise, ankommen → die Ankunft\n\n**Придаточное → предложная группа:**\n\n| Придаточное | Предлог |\n| wenn, falls | bei |\n| weil, da | wegen, aufgrund |\n| obwohl | trotz |\n| nachdem | nach |\n| bevor | vor |\n| als, während | bei, während |\n| damit, um … zu | zu (zum/zur), für |\n| indem | durch |\n\nПодлежащее или дополнение придаточного становится **определением в Genitiv**: Nachdem der Zug angekommen war → nach der Ankunft des Zuges. Weil der Lehrer erkrankt ist → wegen der Erkrankung des Lehrers.\n\nПримеры:\n- Bei Regen fällt das Spiel aus. — В случае дождя игра отменяется.\n- Zur Senkung der Kosten wurde Personal entlassen. — Для снижения затрат сократили персонал.\n- Durch die Einnahme des Medikaments verschwanden die Schmerzen. — Благодаря приёму лекарства боль прошла.\n\n**Типичные ошибки русскоязычных:**\n- придумывают несуществующие слова: «die Senkenung», «die Ankommung» — проверяйте по словарю;\n- забывают Genitiv после существительного: неправильно «die Lösung das Problem», правильно die Lösung des Problems;\n- перегружают текст: номинальный стиль уместен в официальных текстах, но не в разговоре.","q":[{"k":"mc","s":"___ der Ankunft des Zuges rief ich dich an. (= Nachdem der Zug angekommen war)","o":["Nach","Vor","Bei"],"a":0,"ru":"После прибытия поезда я тебе позвонил."},{"k":"mc","s":"___ Regen fällt das Fest aus. (= Wenn es regnet)","o":["Wegen","Bei","Trotz"],"a":1,"ru":"В случае дождя праздник отменяется."},{"k":"mc","s":"Zur ___ der Kosten hat die Firma Personal entlassen. (senken)","o":["Senkenung","Gesenke","Senkung","Senken"],"a":2,"ru":"Для снижения затрат фирма сократила персонал."},{"k":"mc","s":"___ des Medikaments verschwanden die Schmerzen schnell. (= Indem man das Medikament einnahm)","o":["Bei der Einnahme","Zur Einnahme","Vor der Einnahme","Durch die Einnahme"],"a":3,"ru":"Благодаря приёму лекарства боль быстро прошла."},{"k":"type","s":"Nach der ___ des Problems gingen alle nach Hause. (lösen)","a":["Lösung"],"ru":"После решения проблемы все пошли домой."},{"k":"type","s":"Bei der ___ der Daten ist ein Fehler passiert. (übertragen)","a":["Übertragung"],"ru":"При передаче данных произошла ошибка."},{"k":"type","s":"Wegen der ___ der Preise kaufen die Leute weniger. (erhöhen)","a":["Erhöhung"],"ru":"Из-за повышения цен люди покупают меньше."},{"k":"type","s":"Die ___ des Museums ist für Mai geplant. (eröffnen)","a":["Eröffnung"],"ru":"Открытие музея запланировано на май."},{"k":"order","w":["bei","Gefahr","die","Notbremse","ziehen"],"a":["Bei Gefahr die Notbremse ziehen","Die Notbremse bei Gefahr ziehen"],"ru":"В случае опасности дёрнуть стоп-кран."},{"k":"order","w":["wegen","der","Erkrankung","des","Lehrers","fällt","der","Unterricht","aus"],"a":["Wegen der Erkrankung des Lehrers fällt der Unterricht aus","Der Unterricht fällt wegen der Erkrankung des Lehrers aus"],"ru":"Из-за болезни учителя занятия отменяются."},{"k":"tr","ru":"После окончания учёбы она переехала в Мюнхен.","a":["Nach dem Ende des Studiums ist sie nach München gezogen","Nach dem Ende des Studiums ist sie nach München umgezogen","Nach dem Ende des Studiums zog sie nach München","Nach dem Abschluss des Studiums ist sie nach München gezogen","Nach dem Abschluss des Studiums ist sie nach München umgezogen","Nach dem Abschluss des Studiums zog sie nach München","Nach Abschluss des Studiums ist sie nach München gezogen","Nach Abschluss des Studiums ist sie nach München umgezogen","Nach Abschluss des Studiums zog sie nach München","Nach dem Studium ist sie nach München gezogen","Nach dem Studium ist sie nach München umgezogen","Nach dem Studium zog sie nach München","Nach dem Studienabschluss ist sie nach München gezogen","Nach dem Studienabschluss ist sie nach München umgezogen","Nach dem Studienabschluss zog sie nach München"]},{"k":"tr","ru":"В случае дождя игра отменяется.","a":["Bei Regen fällt das Spiel aus","Bei Regen wird das Spiel abgesagt","Das Spiel fällt bei Regen aus","Das Spiel wird bei Regen abgesagt"]}]},{"id":"de-c1-modalverben-subjektiv","lv":"C1","e":"🤔","t":"Субъективное значение модальных глаголов: muss, dürfte, soll, will","x":"Модальные глаголы выражают не только возможность или обязанность, но и **оценку говорящего**: насколько он уверен в информации или откуда её знает. Это **субъективное употребление**.\n\n| Глагол | Значение | Пример |\n| müssen | я почти уверен | Er muss krank sein. — Он, должно быть, болен. |\n| dürfte | вероятно | Das dürfte stimmen. — Это, вероятно, верно. |\n| können / könnte | возможно | Sie könnte im Büro sein. — Она, возможно, в офисе. |\n| sollen | говорят, по сообщениям | Er soll sehr reich sein. — Говорят, он очень богат. |\n| wollen | сам утверждает (с сомнением) | Er will nichts gesehen haben. — Он утверждает, что ничего не видел. |\n\nШкала уверенности: muss (≈ 90 %) → dürfte (≈ 75 %) → kann / könnte (≈ 50 %).\n\n**О прошлом** используется **инфинитив перфекта** (Partizip II + haben/sein), а модальный глагол стоит в настоящем времени:\n- Sie muss den Schlüssel vergessen haben. — Она, должно быть, забыла ключ.\n- Er soll in Paris gewesen sein. — Говорят, он был в Париже.\n- Er will den Brief nie bekommen haben. — Он утверждает, что так и не получил письмо.\n\nПредположение можно выразить и через **werden + Infinitiv**, часто с частицей wohl: Er wird wohl krank sein. — Наверное, он болен.\n\n**Типичные ошибки русскоязычных:**\n- ставят модальный глагол в прошедшее время: для предположения о прошлом нужно Er muss krank gewesen sein, а не «Er musste krank sein»;\n- путают sollen и wollen: sollen — информация от других, wollen — утверждение самого человека;\n- употребляют «darf» вместо dürfte: вероятность выражает только форма Konjunktiv II dürfte.","q":[{"k":"mc","s":"Er ist nicht da. Er ___ krank sein. (я почти уверен)","o":["muss","soll","will"],"a":0,"ru":"Его нет. Он, должно быть, болен."},{"k":"mc","s":"Der Schauspieler ___ sehr reich sein – das steht in der Zeitung. (говорят)","o":["will","soll","muss"],"a":1,"ru":"Говорят, этот актёр очень богат — так пишут в газете."},{"k":"mc","s":"Er ___ den Brief nie bekommen haben – das sagt er jedenfalls selbst.","o":["soll","dürfte","will"],"a":2,"ru":"Он утверждает, что так и не получил письмо."},{"k":"mc","s":"Das Paket ___ morgen ankommen – das ist ziemlich wahrscheinlich.","o":["will","mag","darf","dürfte"],"a":3,"ru":"Посылка, вероятно, придёт завтра."},{"k":"type","s":"Sie ___ gestern in Paris gewesen sein – das hat mir ihr Bruder erzählt. (sollen)","a":["soll"],"ru":"Говорят, она вчера была в Париже — так мне рассказал её брат."},{"k":"type","s":"Er ___ den Fehler gemacht haben – sonst war niemand im Büro. (müssen)","a":["muss"],"ru":"Должно быть, это он сделал ошибку — больше никого в офисе не было."},{"k":"type","s":"Das Restaurant ___ jetzt geschlossen sein, es ist schon nach Mitternacht. (dürfen, вероятность)","a":["dürfte"],"ru":"Ресторан, вероятно, уже закрыт, ведь уже за полночь."},{"k":"type","s":"Er behauptet, er habe nichts gesehen – er ___ nichts gesehen haben. (wollen)","a":["will"],"ru":"Он утверждает, что ничего не видел."},{"k":"order","w":["er","muss","den","Zug","verpasst","haben"],"a":["Er muss den Zug verpasst haben"],"ru":"Он, должно быть, опоздал на поезд."},{"k":"order","w":["sie","soll","sehr","reich","gewesen","sein"],"a":["Sie soll sehr reich gewesen sein"],"ru":"Говорят, она была очень богата."},{"k":"tr","ru":"Говорят, он живёт в Гамбурге. (sollen)","a":["Er soll in Hamburg wohnen","Er soll in Hamburg leben"]},{"k":"tr","ru":"Она, должно быть, забыла ключ. (müssen)","a":["Sie muss den Schlüssel vergessen haben","Sie muss ihren Schlüssel vergessen haben"]}]},{"id":"de-c1-funktionsverbgefuege","lv":"C1","e":"💼","t":"Функционально-глагольные сочетания (Funktionsverbgefüge)","x":"**Функционально-глагольные сочетания** (Funktionsverbgefüge) состоят из существительного и глагола, который почти потерял собственное значение (stellen, nehmen, bringen, kommen, treten, treffen, üben). Основной смысл несёт существительное. Такие выражения типичны для официального и делового языка.\n\n| Сочетание | Значение |\n| eine Entscheidung treffen | принять решение |\n| eine Frage stellen | задать вопрос |\n| einen Antrag stellen (auf + Akk.) | подать заявление |\n| zur Verfügung stellen / stehen | предоставить / быть в распоряжении |\n| in Frage / in Betracht kommen | рассматриваться, подходить |\n| in Betracht ziehen | принимать во внимание |\n| in Kraft treten | вступить в силу |\n| Kritik üben (an + Dat.) | критиковать |\n| Rücksicht nehmen (auf + Akk.) | считаться с кем-то |\n| zum Ausdruck bringen | выразить |\n| Abschied nehmen (von + Dat.) | попрощаться |\n\nЭти сочетания нельзя переводить дословно с русского: «принять решение» — не «eine Entscheidung nehmen», а **treffen**; «задать вопрос» — не «geben», а **stellen**. Их учат целиком, вместе с предлогом и артиклем.\n\nПримеры:\n- Das Gesetz tritt am 1. Januar in Kraft. — Закон вступает в силу 1 января.\n- Die Firma stellt den Mitarbeitern Laptops zur Verfügung. — Фирма предоставляет сотрудникам ноутбуки.\n\nСуществительное с предлогом стоит в конце предложения, рядом с глаголом: Wir müssen diese Möglichkeit in Betracht ziehen. — Мы должны учесть эту возможность.\n\n**Типичные ошибки русскоязычных:**\n- калька с русского: «eine Entscheidung machen», «eine Frage geben»;\n- неправильный предлог или артикль: «in die Kraft treten», «zu der Verfügung»;\n- замена глагола синонимом: «Kritik machen» вместо Kritik üben.","q":[{"k":"mc","s":"Wir müssen bis Freitag eine Entscheidung ___.","o":["treffen","machen","stellen"],"a":0,"ru":"Мы должны принять решение до пятницы."},{"k":"mc","s":"Das neue Gesetz tritt am 1. Januar in ___.","o":["Frage","Kraft","Betracht"],"a":1,"ru":"Новый закон вступает в силу 1 января."},{"k":"mc","s":"Die Firma stellt den Mitarbeitern Laptops zur ___.","o":["Sprache","Kenntnis","Verfügung"],"a":2,"ru":"Фирма предоставляет сотрудникам ноутбуки."},{"k":"mc","s":"Bitte nehmen Sie ___ auf die anderen Gäste.","o":["Abschied","Anspruch","Kritik","Rücksicht"],"a":3,"ru":"Пожалуйста, считайтесь с другими гостями."},{"k":"type","s":"Darf ich Ihnen eine Frage ___? (задать)","a":["stellen"],"ru":"Можно задать Вам вопрос?"},{"k":"type","s":"Der Kandidat kommt für die Stelle nicht in ___. (рассматриваться)","a":["Frage","Betracht"],"ru":"Этот кандидат на должность не рассматривается."},{"k":"type","s":"Die Opposition ___ scharfe Kritik an der Regierung. (üben, Präsens)","a":["übt"],"ru":"Оппозиция резко критикует правительство."},{"k":"type","s":"Er brachte seine Dankbarkeit zum ___. (выразил)","a":["Ausdruck"],"ru":"Он выразил свою благодарность."},{"k":"order","w":["wir","müssen","diese","Möglichkeit","in","Betracht","ziehen"],"a":["Wir müssen diese Möglichkeit in Betracht ziehen","Diese Möglichkeit müssen wir in Betracht ziehen"],"ru":"Мы должны принять во внимание эту возможность."},{"k":"order","w":["sie","hat","einen","Antrag","auf","ein","Stipendium","gestellt"],"a":["Sie hat einen Antrag auf ein Stipendium gestellt"],"ru":"Она подала заявление на стипендию."},{"k":"tr","ru":"Мы примем решение завтра.","a":["Wir treffen morgen eine Entscheidung","Wir treffen morgen die Entscheidung","Morgen treffen wir eine Entscheidung","Morgen treffen wir die Entscheidung","Wir werden morgen eine Entscheidung treffen","Wir werden morgen eine Entscheidung fällen","Wir werden morgen die Entscheidung treffen","Wir werden morgen die Entscheidung fällen","Morgen werden wir eine Entscheidung treffen","Morgen werden wir eine Entscheidung fällen","Morgen werden wir die Entscheidung treffen","Morgen werden wir die Entscheidung fällen","Wir fällen morgen eine Entscheidung","Wir fällen morgen die Entscheidung","Morgen fällen wir eine Entscheidung","Morgen fällen wir die Entscheidung","Wir treffen die Entscheidung morgen","Wir werden die Entscheidung morgen treffen","Wir entscheiden morgen","Morgen entscheiden wir","Wir werden morgen entscheiden","Morgen werden wir entscheiden"]},{"k":"tr","ru":"Закон вступил в силу в прошлом году.","a":["Das Gesetz ist letztes Jahr in Kraft getreten","Das Gesetz ist im letzten Jahr in Kraft getreten","Das Gesetz ist im vergangenen Jahr in Kraft getreten","Das Gesetz ist vergangenes Jahr in Kraft getreten","Das Gesetz ist voriges Jahr in Kraft getreten","Das Gesetz trat letztes Jahr in Kraft","Das Gesetz trat im letzten Jahr in Kraft","Das Gesetz trat im vergangenen Jahr in Kraft","Das Gesetz trat vergangenes Jahr in Kraft","Das Gesetz trat voriges Jahr in Kraft","Letztes Jahr ist das Gesetz in Kraft getreten","Letztes Jahr trat das Gesetz in Kraft","Im letzten Jahr ist das Gesetz in Kraft getreten","Im letzten Jahr trat das Gesetz in Kraft","Im vergangenen Jahr ist das Gesetz in Kraft getreten","Im vergangenen Jahr trat das Gesetz in Kraft","Vergangenes Jahr ist das Gesetz in Kraft getreten","Vergangenes Jahr trat das Gesetz in Kraft","Voriges Jahr ist das Gesetz in Kraft getreten","Voriges Jahr trat das Gesetz in Kraft"]}]},{"id":"de-c1-konnektoren","lv":"C1","e":"🧵","t":"Коннекторы и связность текста: folglich, dennoch, indem, zumal","x":"Связный текст уровня C1 требует разнообразных **коннекторов**. Главное — знать, какой порядок слов вызывает каждый из них.\n\n**1. Сочинительные союзы (позиция 0, прямой порядок):** aber, denn, sondern, doch, und, oder.\n\n**2. Союзные наречия (позиция 1, сразу за ними глагол):** deshalb, folglich, infolgedessen (следовательно), trotzdem, dennoch (тем не менее), allerdings (однако), außerdem, stattdessen.\nDer Zug hatte Verspätung, folglich verpasste ich den Anschluss. — Поезд опоздал, поэтому я не успел на пересадку.\n\n**3. Подчинительные союзы (глагол в конце):**\n\n| Союз | Значение |\n| indem | тем, что; путём (способ) |\n| sodass / so …, dass | так что (следствие) |\n| zumal | тем более что |\n| sofern | если, при условии что |\n| wohingegen, während | тогда как |\n| insofern als | постольку, поскольку |\n\n- Man spart Energie, indem man das Licht ausschaltet. — Энергию экономят, выключая свет.\n- Er lernte viel, sodass er die Prüfung bestand. — Он много учился, так что сдал экзамен.\n- Sie spricht gut Deutsch, zumal sie in Wien aufgewachsen ist. — Она хорошо говорит по-немецки, тем более что выросла в Вене.\n\n**Es sei denn** (разве что, если только не) — после него прямой порядок слов: Ich komme, es sei denn, es regnet stark.\n\nНаречия trotzdem и dennoch могут стоять и в середине предложения: Wir gingen trotzdem wandern.\n\n**Типичные ошибки русскоязычных:**\n- путают obwohl и trotzdem: неправильно «Er war krank, obwohl kam er» — после obwohl глагол в конце, после trotzdem — сразу глагол;\n- после союзных наречий не делают инверсию: неправильно «folglich ich verpasste»;\n- переводят «тем, что» как dass вместо indem.","q":[{"k":"mc","s":"Er war krank, ___ kam er zur Arbeit.","o":["dennoch","obwohl","denn"],"a":0,"ru":"Он был болен, тем не менее пришёл на работу."},{"k":"mc","s":"Man spart Energie, ___ man das Licht ausschaltet.","o":["sodass","indem","dennoch"],"a":1,"ru":"Энергию экономят, выключая свет."},{"k":"mc","s":"Ich komme morgen, ___, es regnet stark.","o":["sofern","falls","es sei denn"],"a":2,"ru":"Я приду завтра, разве что будет сильный дождь."},{"k":"mc","s":"Ich nehme das Angebot an, ___ die Bedingungen stimmen.","o":["folglich","dennoch","trotzdem","sofern"],"a":3,"ru":"Я приму предложение, если условия подойдут."},{"k":"type","s":"Sie spricht gut Deutsch, ___ sie in Wien aufgewachsen ist. (тем более что)","a":["zumal"],"ru":"Она хорошо говорит по-немецки, тем более что выросла в Вене."},{"k":"type","s":"Es war so kalt, ___ der See zugefroren ist. (что — следствие)","a":["dass"],"ru":"Было так холодно, что озеро замёрзло."},{"k":"type","s":"Ich helfe dir gern, ___ ich Zeit habe. (при условии что)","a":["sofern","falls","wenn"],"ru":"Я охотно помогу тебе, если у меня будет время."},{"k":"type","s":"Er wohnt auf dem Land, ___ seine Schwester in der Stadt lebt. (тогда как)","a":["wohingegen","während"],"ru":"Он живёт в деревне, тогда как его сестра живёт в городе."},{"k":"order","w":["das","Wetter","war","schlecht","trotzdem","gingen","wir","wandern"],"a":["Das Wetter war schlecht trotzdem gingen wir wandern","Das Wetter war schlecht wir gingen trotzdem wandern"],"ru":"Погода была плохая, тем не менее мы пошли в поход."},{"k":"order","w":["er","lernte","viel","sodass","er","die","Prüfung","bestand"],"a":["Er lernte viel sodass er die Prüfung bestand"],"ru":"Он много учился, так что сдал экзамен."},{"k":"tr","ru":"Он устал, тем не менее продолжал работать.","a":["Er war müde, dennoch arbeitete er weiter","Er war müde, trotzdem arbeitete er weiter","Er war müde, er arbeitete dennoch weiter","Er war müde, er arbeitete trotzdem weiter","Er war müde, dennoch hat er weitergearbeitet","Er war müde, trotzdem hat er weitergearbeitet","Er war müde, er hat dennoch weitergearbeitet","Er war müde, er hat trotzdem weitergearbeitet"]},{"k":"tr","ru":"Она учит язык, слушая подкасты. (indem)","a":["Sie lernt die Sprache, indem sie Podcasts hört","Sie lernt die Sprache, indem sie sich Podcasts anhört"]}]},{"id":"de-c2-modalpartikeln","lv":"C2","e":"💬","t":"Модальные частицы: doch, ja, mal, denn, eben, wohl","x":"**Модальные частицы** — короткие слова, которые не меняют смысл предложения, но передают отношение говорящего: удивление, нетерпение, дружелюбие, упрёк. Частицы безударны и стоят в середине предложения, обычно после спрягаемого глагола и местоимений.\n\n| Частица | Функция | Пример |\n| doch | смягчённый призыв; напоминание | Komm doch rein! — Заходи же! |\n| ja | общеизвестный факт; удивление | Du kennst ja meinen Bruder. — Ты ведь знаешь моего брата. |\n| mal | смягчение просьбы | Hilf mir mal! — Помоги-ка мне! |\n| denn | интерес или удивление в вопросе | Was ist denn los? — Что же случилось? |\n| eben / halt | так уж есть, ничего не поделаешь | Das ist eben so. — Так уж вышло. |\n| wohl | предположение | Er wird wohl krank sein. — Он, наверное, болен. |\n| etwa | удивление, ожидание ответа «нет» | Bist du etwa schon fertig? — Неужели ты уже готов? |\n| bloß / nur | предостережение; отчаяние | Sei bloß vorsichtig! — Смотри, будь осторожен! |\n| schon | успокоение, уверенность | Das klappt schon. — Всё получится. |\n\nОдна и та же частица в разных типах предложений даёт разный оттенок: doch в побудительном предложении смягчает просьбу, в повествовательном означает «ведь»; ja в восклицании выражает удивление: Das ist ja toll! — Да это же здорово!\n\nЧастицы часто комбинируются: Komm doch mal vorbei! — Заходи как-нибудь!\n\n**Типичные ошибки русскоязычных:**\n- совсем не используют частицы, и просьбы без mal или doch звучат как приказ;\n- ставят частицу на первое место: неправильно «Doch komm rein»;\n- употребляют denn как частицу в повествовательном предложении — она возможна только в вопросе.","q":[{"k":"mc","s":"Was ist ___ los mit dir?","o":["denn","ja","mal"],"a":0,"ru":"Что же с тобой случилось?"},{"k":"mc","s":"Komm ___ rein! (дружелюбное приглашение)","o":["denn","doch","ja"],"a":1,"ru":"Заходи же!"},{"k":"mc","s":"Du kennst ___ meinen Bruder – er war auch auf der Party. (известно обоим)","o":["denn","mal","ja"],"a":2,"ru":"Ты ведь знаешь моего брата — он тоже был на вечеринке."},{"k":"mc","s":"Das ist ___ so, da kann man nichts machen. (так уж есть)","o":["denn","bloß","etwa","eben"],"a":3,"ru":"Так уж оно есть, ничего не поделаешь."},{"k":"type","s":"Hilf mir ___ kurz! (смягчение просьбы: «-ка»)","a":["mal"],"ru":"Помоги-ка мне быстренько!"},{"k":"type","s":"Er ist nicht da? Er wird ___ krank sein. (предположение: наверное)","a":["wohl"],"ru":"Его нет? Он, наверное, болен."},{"k":"type","s":"Bist du ___ schon fertig? (удивление «неужели», ожидаю «нет»; не denn)","a":["etwa"],"ru":"Неужели ты уже готов?"},{"k":"type","s":"Sei ___ vorsichtig! (предостережение: «смотри»)","a":["bloß","ja"],"ru":"Смотри, будь осторожен!"},{"k":"order","w":["das","habe","ich","dir","doch","gesagt"],"a":["Das habe ich dir doch gesagt","Ich habe dir das doch gesagt"],"ru":"Я же тебе это говорил."},{"k":"order","w":["kannst","du","mir","mal","helfen"],"a":["Kannst du mir mal helfen"],"ru":"Можешь мне помочь?"},{"k":"tr","ru":"Заходи же! (к другу)","a":["Komm doch rein","Komm doch herein","Komm doch mal rein","Komm mal rein"]},{"k":"tr","ru":"Ты ведь знаешь, что я не люблю кофе.","a":["Du weißt doch, dass ich keinen Kaffee mag","Du weißt doch, dass ich Kaffee nicht mag","Du weißt doch, dass ich Kaffee nicht gern trinke","Du weißt doch, dass ich nicht gern Kaffee trinke","Du weißt ja, dass ich keinen Kaffee mag","Du weißt ja, dass ich Kaffee nicht mag","Du weißt ja, dass ich Kaffee nicht gern trinke","Du weißt ja, dass ich nicht gern Kaffee trinke"]}]},{"id":"de-c2-irreal-konzessiv","lv":"C2","e":"🌫️","t":"Ирреальное сравнение (als ob) и уступительные конструкции (wie … auch)","x":"**Ирреальное сравнение** описывает то, что только кажется: «как будто, словно». После **als ob / als wenn** спрягаемый глагол стоит в конце, после одного **als** — сразу за союзом. Используется Konjunktiv II.\n- Er tut so, als ob er alles wüsste. = Er tut so, als wüsste er alles. — Он делает вид, будто всё знает.\nДля прошлого: Er sieht aus, als hätte er nicht geschlafen. — Он выглядит так, будто не спал.\n\n**Уступительные конструкции** выражают «даже если, хотя, как бы ни»:\n\n| Конструкция | Значение | Пример |\n| selbst wenn / auch wenn | даже если | Selbst wenn es regnet, machen wir den Ausflug. |\n| wenn … auch | хотя и | Wenn es auch schwer ist, ich gebe nicht auf. |\n| so + прилагательное + auch | как ни | So sehr er sich auch bemüht, er schafft es nicht. |\n| wie + прилагательное + auch | каким бы … ни | Wie teuer das Kleid auch ist, sie kauft es. |\n| was / wer / wo … auch (immer) | что / кто / где бы ни | Was du auch sagst, ich glaube dir nicht. |\n\n**Порядок слов:** после уступительного придаточного с auch главное предложение обычно начинается **без инверсии**: So sehr er sich auch bemüht, er schafft es nicht. После selbst wenn / auch wenn возможны оба варианта.\n\n**Типичные ошибки русскоязычных:**\n- после als ob ставят индикатив: неправильно «als ob er alles weiß», нужно wüsste;\n- после als без ob ставят глагол в конец: неправильно «als er alles wüsste», правильно als wüsste er alles;\n- забывают частицу auch: неправильно «Wie teuer das Kleid ist, sie kauft es».","q":[{"k":"mc","s":"Er tut so, als ___ er nichts gehört.","o":["hätte","hat","würde"],"a":0,"ru":"Он делает вид, будто ничего не слышал."},{"k":"mc","s":"Sie spricht, als ob sie die Chefin ___.","o":["ist","wäre","war"],"a":1,"ru":"Она говорит так, как будто она начальница."},{"k":"mc","s":"So sehr er sich auch ___, er schafft es nicht.","o":["bemühte","bemühen","bemüht"],"a":2,"ru":"Как он ни старается, у него не получается."},{"k":"mc","s":"___ du auch sagst, ich glaube dir nicht.","o":["Wie","Ob","Wenn","Was"],"a":3,"ru":"Что бы ты ни говорил, я тебе не верю."},{"k":"type","s":"Er sieht aus, als ___ er die ganze Nacht nicht geschlafen. (haben, Konjunktiv II)","a":["hätte"],"ru":"Он выглядит так, будто всю ночь не спал."},{"k":"type","s":"Selbst wenn es regnet, ___ wir den Ausflug. (machen, Präsens)","a":["machen"],"ru":"Даже если будет дождь, мы поедем на экскурсию."},{"k":"type","s":"Wie teuer das Kleid auch ___, sie kauft es. (sein, Präsens)","a":["ist"],"ru":"Каким бы дорогим ни было платье, она его купит."},{"k":"type","s":"Sie lächelte, als ___ nichts geschehen. (sein, Konjunktiv II)","a":["wäre"],"ru":"Она улыбалась, как будто ничего не случилось."},{"k":"order","w":["er","tut","so","als","ob","er","alles","wüsste"],"a":["Er tut so als ob er alles wüsste"],"ru":"Он делает вид, будто всё знает."},{"k":"order","w":["auch","wenn","es","schwer","ist","ich","gebe","nicht","auf"],"a":["Auch wenn es schwer ist gebe ich nicht auf","Auch wenn es schwer ist ich gebe nicht auf","Ich gebe nicht auf auch wenn es schwer ist","Wenn es auch schwer ist gebe ich nicht auf","Wenn es auch schwer ist ich gebe nicht auf","Ich gebe nicht auf wenn es auch schwer ist"],"ru":"Даже если это трудно, я не сдаюсь."},{"k":"tr","ru":"Он ведёт себя так, будто он здесь начальник.","a":["Er benimmt sich, als ob er hier der Chef wäre","Er benimmt sich, als wenn er hier der Chef wäre","Er benimmt sich, als wäre er hier der Chef","Er benimmt sich, als ob er hier der Boss wäre","Er benimmt sich, als wäre er hier der Boss","Er verhält sich, als ob er hier der Chef wäre","Er verhält sich, als wenn er hier der Chef wäre","Er verhält sich, als wäre er hier der Chef","Er verhält sich, als ob er hier der Boss wäre","Er verhält sich, als wäre er hier der Boss","Er tut so, als ob er hier der Chef wäre","Er tut so, als wenn er hier der Chef wäre","Er tut so, als wäre er hier der Chef","Er tut so, als ob er hier der Boss wäre","Er tut so, als wäre er hier der Boss"]},{"k":"tr","ru":"Даже если он придёт, я не буду с ним разговаривать.","a":["Selbst wenn er kommt, rede ich nicht mit ihm","Selbst wenn er kommt, spreche ich nicht mit ihm","Selbst wenn er kommt, werde ich nicht mit ihm reden","Selbst wenn er kommt, werde ich nicht mit ihm sprechen","Selbst wenn er kommt, ich rede nicht mit ihm","Selbst wenn er kommt, ich spreche nicht mit ihm","Selbst wenn er kommt, ich werde nicht mit ihm reden","Selbst wenn er kommt, ich werde nicht mit ihm sprechen","Auch wenn er kommt, rede ich nicht mit ihm","Auch wenn er kommt, spreche ich nicht mit ihm","Auch wenn er kommt, werde ich nicht mit ihm reden","Auch wenn er kommt, werde ich nicht mit ihm sprechen","Auch wenn er kommt, ich rede nicht mit ihm","Auch wenn er kommt, ich spreche nicht mit ihm","Auch wenn er kommt, ich werde nicht mit ihm reden","Auch wenn er kommt, ich werde nicht mit ihm sprechen","Sogar wenn er kommt, rede ich nicht mit ihm","Sogar wenn er kommt, spreche ich nicht mit ihm","Sogar wenn er kommt, werde ich nicht mit ihm reden","Sogar wenn er kommt, werde ich nicht mit ihm sprechen","Sogar wenn er kommt, ich rede nicht mit ihm","Sogar wenn er kommt, ich spreche nicht mit ihm","Sogar wenn er kommt, ich werde nicht mit ihm reden","Sogar wenn er kommt, ich werde nicht mit ihm sprechen","Ich rede nicht mit ihm, selbst wenn er kommt","Ich rede nicht mit ihm, auch wenn er kommt","Ich spreche nicht mit ihm, selbst wenn er kommt","Ich spreche nicht mit ihm, auch wenn er kommt","Ich werde nicht mit ihm reden, selbst wenn er kommt","Ich werde nicht mit ihm reden, auch wenn er kommt","Ich werde nicht mit ihm sprechen, selbst wenn er kommt","Ich werde nicht mit ihm sprechen, auch wenn er kommt"]}]},{"id":"de-c2-gehobene-praepositionen","lv":"C2","e":"🎩","t":"Книжные предлоги: angesichts, ungeachtet, zufolge, mangels","x":"В официальных, юридических и научных текстах употребляются **книжные предлоги**. Большинство из них требует **Genitiv**.\n\n| Предлог | Значение | Пример |\n| angesichts | ввиду, перед лицом | angesichts der Lage |\n| ungeachtet | несмотря на | ungeachtet der Warnungen |\n| anlässlich | по случаю | anlässlich seines Geburtstags |\n| mangels | за неимением | mangels Beweisen |\n| zwecks | с целью | zwecks Besprechung |\n| zugunsten | в пользу | zugunsten der Kinder |\n| infolge | вследствие | infolge des Unfalls |\n| hinsichtlich, bezüglich | относительно | hinsichtlich der Kosten |\n| seitens | со стороны | seitens der Regierung |\n\n**С Dativ:** **entgegen** (вопреки): entgegen allen Erwartungen; **gemäß** и **entsprechend** (согласно), часто после существительного: den Vorschriften gemäß.\n\n**zufolge** (согласно, по сообщению) стоит **после** существительного и требует Dativ: dem Bericht zufolge, seiner Aussage zufolge. Не путайте с **laut** — он стоит перед существительным: laut Bericht.\n\nЕсли Genitiv множественного числа без артикля не виден по форме, используется Dativ: mangels Beweisen.\n\nПримеры:\n- Angesichts der Lage wird die Versammlung verschoben. — Ввиду ситуации собрание переносится.\n- Anlässlich seines 60. Geburtstags gab er ein großes Fest. — По случаю 60-летия он устроил большой праздник.\n- Ungeachtet der Warnungen fuhr er weiter. — Несмотря на предупреждения, он поехал дальше.\n\n**Типичные ошибки русскоязычных:**\n- ставят zufolge перед существительным: неправильно «zufolge dem Bericht», правильно dem Bericht zufolge;\n- используют Akkusativ по аналогии с русским «несмотря на»: неправильно «ungeachtet die Warnungen»;\n- употребляют книжные предлоги в разговоре, где естественнее wegen, trotz, für.","q":[{"k":"mc","s":"___ der hohen Inflation steigen die Zinsen.","o":["Angesichts","Zwecks","Mangels"],"a":0,"ru":"Ввиду высокой инфляции растут процентные ставки."},{"k":"mc","s":"Dem Bericht ___ ist die Zahl der Arbeitslosen gesunken.","o":["anlässlich","zufolge","angesichts"],"a":1,"ru":"Согласно докладу, число безработных сократилось."},{"k":"mc","s":"___ Beweisen wurde der Angeklagte freigesprochen.","o":["Zwecks","Anlässlich","Mangels"],"a":2,"ru":"За недостатком доказательств обвиняемого оправдали."},{"k":"mc","s":"___ seines 60. Geburtstags gab er ein großes Fest.","o":["Mangels","Zwecks","Kraft","Anlässlich"],"a":3,"ru":"По случаю 60-летия он устроил большой праздник."},{"k":"type","s":"Ungeachtet ___ Warnungen fuhr er weiter. (die, Plural)","a":["der"],"ru":"Несмотря на предупреждения, он поехал дальше."},{"k":"type","s":"Entgegen ___ Erwartungen gewann die Mannschaft. (alle)","a":["allen"],"ru":"Вопреки всем ожиданиям команда победила."},{"k":"type","s":"Er verzichtete zugunsten ___ jüngeren Kollegin auf die Stelle. (seine)","a":["seiner"],"ru":"Он отказался от должности в пользу своей более молодой коллеги."},{"k":"type","s":"Den Vorschriften ___ müssen alle Geräte geprüft werden. (согласно, после существительного; не zufolge)","a":["gemäß","entsprechend"],"ru":"Согласно предписаниям, все приборы должны быть проверены."},{"k":"order","w":["angesichts","der","Lage","bleiben","wir","zu","Hause"],"a":["Angesichts der Lage bleiben wir zu Hause","Wir bleiben angesichts der Lage zu Hause"],"ru":"Ввиду ситуации мы остаёмся дома."},{"k":"order","w":["seiner","Aussage","zufolge","war","er","nicht","dort"],"a":["Seiner Aussage zufolge war er nicht dort","Er war seiner Aussage zufolge nicht dort"],"ru":"По его словам, его там не было."},{"k":"tr","ru":"Ввиду ситуации собрание переносится.","a":["Angesichts der Lage wird die Versammlung verschoben","Angesichts der Lage wird die Sitzung verschoben","Angesichts der Situation wird die Versammlung verschoben","Angesichts der Situation wird die Sitzung verschoben","Die Versammlung wird angesichts der Lage verschoben","Die Versammlung wird angesichts der Situation verschoben","Die Sitzung wird angesichts der Lage verschoben","Die Sitzung wird angesichts der Situation verschoben"]},{"k":"tr","ru":"Согласно прогнозу, завтра будет дождь.","a":["Der Prognose zufolge regnet es morgen","Der Prognose zufolge wird es morgen regnen","Der Prognose zufolge gibt es morgen Regen","Der Vorhersage zufolge regnet es morgen","Der Vorhersage zufolge wird es morgen regnen","Der Vorhersage zufolge gibt es morgen Regen","Der Wettervorhersage zufolge regnet es morgen","Der Wettervorhersage zufolge wird es morgen regnen","Der Wettervorhersage zufolge gibt es morgen Regen","Laut Prognose regnet es morgen","Laut Prognose wird es morgen regnen","Laut Prognose gibt es morgen Regen","Laut der Prognose regnet es morgen","Laut der Prognose wird es morgen regnen","Laut der Prognose gibt es morgen Regen","Laut Vorhersage regnet es morgen","Laut Vorhersage wird es morgen regnen","Laut Vorhersage gibt es morgen Regen","Laut der Vorhersage regnet es morgen","Laut der Vorhersage wird es morgen regnen","Laut der Vorhersage gibt es morgen Regen","Laut Wettervorhersage regnet es morgen","Laut Wettervorhersage wird es morgen regnen","Laut Wettervorhersage gibt es morgen Regen","Laut der Wettervorhersage regnet es morgen","Laut der Wettervorhersage wird es morgen regnen","Laut der Wettervorhersage gibt es morgen Regen"]}]},{"id":"de-c2-verbalisierung","lv":"C2","e":"🔁","t":"Вербализация: от номинального стиля к глагольному","x":"На уровне C2 нужно уметь не только сжимать текст в номинальный стиль, но и **разворачивать** его обратно, делая понятным и живым. Это **вербализация**: предложная группа превращается в придаточное предложение.\n\n| Предлог | Союз | Пример |\n| bei | wenn, falls / als | bei Regen → wenn es regnet |\n| wegen, aufgrund | weil, da | wegen der Erkrankung des Fahrers → weil der Fahrer erkrankt war |\n| trotz | obwohl | trotz intensiver Suche → obwohl man intensiv suchte |\n| nach | nachdem | nach Abschluss der Arbeiten → nachdem die Arbeiten abgeschlossen sind |\n| vor | bevor | vor der Abreise der Gäste → bevor die Gäste abreisen |\n| zu, zwecks | damit, um … zu | zur Verbesserung der Qualität → damit die Qualität verbessert wird |\n| durch | indem, dadurch dass | durch Training → indem er trainiert |\n\n**Правила преобразования:**\n- существительное становится глаголом: die Überprüfung → überprüfen;\n- Genitiv-определение становится подлежащим или дополнением: die Abreise der Gäste → die Gäste reisen ab;\n- если исполнитель неизвестен, используют **man** или **пассив**;\n- прилагательное становится наречием: intensive Suche → man sucht intensiv;\n- соблюдают последовательность времён: после nachdem — Perfekt или Plusquamperfekt.\n\nПример: Bei Nichtbeachtung der Regeln droht eine Strafe. → Wenn man die Regeln nicht beachtet, droht eine Strafe. — Если не соблюдать правила, грозит штраф.\n\n**Типичные ошибки русскоязычных:**\n- выбирают неверный союз: bei переводят через weil вместо wenn или als;\n- путают um … zu и damit: при разных подлежащих нужен damit;\n- забывают порядок слов: в придаточном спрягаемый глагол стоит в конце (…, weil der Fahrer erkrankt war).","q":[{"k":"mc","s":"Bei Nichtbeachtung der Regeln droht eine Strafe. = ___ man die Regeln nicht beachtet, droht eine Strafe.","o":["Wenn","Weil","Obwohl"],"a":0,"ru":"Если не соблюдать правила, грозит штраф."},{"k":"mc","s":"Trotz intensiver Suche fand man das Kind nicht. = ___ man intensiv suchte, fand man das Kind nicht.","o":["Weil","Obwohl","Nachdem"],"a":1,"ru":"Несмотря на интенсивные поиски, ребёнка не нашли."},{"k":"mc","s":"Zur Verbesserung der Qualität investiert die Firma viel. = Die Firma investiert viel, ___ die Qualität verbessert wird.","o":["um","indem","damit"],"a":2,"ru":"Фирма много инвестирует, чтобы улучшить качество."},{"k":"mc","s":"Nach Abschluss der Bauarbeiten wird die Straße geöffnet. = Nachdem die Bauarbeiten ___ sind, wird die Straße geöffnet.","o":["abschließen","abgeschlossen werden","abschließend","abgeschlossen"],"a":3,"ru":"После завершения строительных работ улицу откроют."},{"k":"type","s":"Durch regelmäßiges Training verbesserte er seine Kondition. = Er verbesserte seine Kondition, ___ er regelmäßig trainierte. (способ)","a":["indem","dadurch dass"],"ru":"Он улучшил свою физическую форму, регулярно тренируясь."},{"k":"type","s":"Vor der Abreise der Gäste räumen wir auf. = Bevor die Gäste ___, räumen wir auf. (abreisen)","a":["abreisen"],"ru":"Перед отъездом гостей мы наводим порядок."},{"k":"type","s":"Wegen der Erkrankung des Fahrers fiel die Fahrt aus. = Die Fahrt fiel aus, weil der Fahrer ___ war. (erkranken)","a":["erkrankt"],"ru":"Поездка не состоялась, потому что водитель заболел."},{"k":"type","s":"Bei der Überprüfung der Daten fand man Fehler. = Als man die Daten ___, fand man Fehler. (überprüfen, Präteritum)","a":["überprüfte"],"ru":"При проверке данных обнаружили ошибки."},{"k":"order","w":["weil","die","Preise","gestiegen","sind","kaufen","die","Menschen","weniger"],"a":["Weil die Preise gestiegen sind kaufen die Menschen weniger","Die Menschen kaufen weniger weil die Preise gestiegen sind"],"ru":"Из-за роста цен люди покупают меньше."},{"k":"order","w":["obwohl","er","sich","bemühte","scheiterte","er"],"a":["Obwohl er sich bemühte scheiterte er","Er scheiterte obwohl er sich bemühte"],"ru":"Несмотря на старания, он потерпел неудачу."},{"k":"tr","ru":"Перед отъездом он позвонил матери. (придаточное с bevor)","a":["Bevor er abreiste, rief er seine Mutter an","Bevor er abreiste, hat er seine Mutter angerufen","Bevor er abreiste, rief er die Mutter an","Bevor er abreiste, hat er die Mutter angerufen","Bevor er abfuhr, rief er seine Mutter an","Bevor er abfuhr, hat er seine Mutter angerufen","Bevor er abfuhr, rief er die Mutter an","Bevor er abfuhr, hat er die Mutter angerufen","Bevor er wegfuhr, rief er seine Mutter an","Bevor er wegfuhr, hat er seine Mutter angerufen","Bevor er wegfuhr, rief er die Mutter an","Bevor er wegfuhr, hat er die Mutter angerufen","Er rief seine Mutter an, bevor er abreiste","Er rief seine Mutter an, bevor er abfuhr","Er rief seine Mutter an, bevor er wegfuhr","Er hat seine Mutter angerufen, bevor er abreiste","Er hat seine Mutter angerufen, bevor er abfuhr","Er hat seine Mutter angerufen, bevor er wegfuhr"]},{"k":"tr","ru":"Если погода будет плохой, экскурсия отменяется. (придаточное)","a":["Wenn das Wetter schlecht ist, fällt der Ausflug aus","Wenn das Wetter schlecht ist, wird der Ausflug abgesagt","Wenn das Wetter schlecht ist, fällt die Exkursion aus","Wenn das Wetter schlecht ist, wird die Exkursion abgesagt","Falls das Wetter schlecht ist, fällt der Ausflug aus","Falls das Wetter schlecht ist, wird der Ausflug abgesagt","Falls das Wetter schlecht ist, fällt die Exkursion aus","Falls das Wetter schlecht ist, wird die Exkursion abgesagt","Wenn das Wetter schlecht wird, fällt der Ausflug aus","Wenn das Wetter schlecht wird, wird der Ausflug abgesagt","Wenn das Wetter schlecht wird, fällt die Exkursion aus","Wenn das Wetter schlecht wird, wird die Exkursion abgesagt","Falls das Wetter schlecht wird, fällt der Ausflug aus","Falls das Wetter schlecht wird, wird der Ausflug abgesagt","Falls das Wetter schlecht wird, fällt die Exkursion aus","Falls das Wetter schlecht wird, wird die Exkursion abgesagt"]}]},{"id":"de-c2-satzbau-stil","lv":"C2","e":"🎭","t":"Порядок слов как стилистическое средство: Vorfeld, Nachfeld, бессоюзные условные предложения","x":"Порядок слов в немецком — гибкий инструмент стиля. С его помощью расставляют акценты и делают текст яснее.\n\n**1. Vorfeld (позиция перед спрягаемым глаголом).** Сюда ставят то, что связывает предложение с предыдущим текстом, или то, что хотят подчеркнуть: Über deinen Besuch habe ich mich sehr gefreut. Если подлежащее несёт новую информацию и его переносят дальше, Vorfeld заполняет **es**: Es kamen viele Gäste. Es wurde viel diskutiert. Если на первом месте стоит другое слово, es исчезает: Gestern kamen viele Gäste.\n\n**2. Nachfeld (Ausklammerung).** За вторую часть сказуемого выносят сравнения с als / wie и длинные предложные группы — так предложение легче понять:\n- Er hat mehr verdient als sein Bruder. — Он заработал больше брата.\n- Ich habe mich gefreut über deinen Besuch. (разговорный оттенок)\n\n**3. Бессоюзные условные предложения.** Вместо wenn спрягаемый глагол ставится на первое место:\n- Sollten Sie Fragen haben, rufen Sie uns an. — Если у Вас возникнут вопросы, позвоните нам.\n- Hätte ich das gewusst, wäre ich nicht gekommen. — Знай я это, я бы не пришёл.\n- Ist das Wasser warm, so können wir schwimmen.\nГлавное предложение часто вводится словами **so** или **dann**.\n\n| С союзом | Без союза |\n| Wenn Sie Fragen haben, … | Sollten Sie Fragen haben, … |\n| Wenn ich das gewusst hätte, … | Hätte ich das gewusst, … |\n\nФорма с **sollte** звучит вежливо и типична для деловых писем.\n\n**Типичные ошибки русскоязычных:**\n- сохраняют es при занятом Vorfeld: неправильно «Gestern es kamen viele Gäste»;\n- вставляют сравнение внутрь рамки: неуклюже «Er hat als sein Bruder mehr verdient»;\n- добавляют wenn к бессоюзному условному: неправильно «Wenn sollten Sie…».","q":[{"k":"mc","s":"___ Sie noch Fragen haben, wenden Sie sich an uns.","o":["Sollten","Dürften","Mögen"],"a":0,"ru":"Если у Вас ещё будут вопросы, обращайтесь к нам."},{"k":"mc","s":"___ ich das gewusst, wäre ich nicht gekommen.","o":["Wenn","Hätte","Habe"],"a":1,"ru":"Знай я это, я бы не пришёл."},{"k":"mc","s":"___ kamen viele Gäste zur Feier.","o":["Er","Das","Es"],"a":2,"ru":"На праздник пришло много гостей."},{"k":"mc","s":"Welche Variante ist stilistisch am natürlichsten? ___","o":["Er hat als sein Bruder mehr verdient.","Er als sein Bruder hat mehr verdient.","Als sein Bruder er hat mehr verdient.","Er hat mehr verdient als sein Bruder."],"a":3,"ru":"Он заработал больше, чем его брат."},{"k":"type","s":"___ du Hilfe brauchen, ruf mich an. (sollen, Konjunktiv II, без wenn)","a":["Solltest"],"ru":"Если тебе понадобится помощь, позвони мне."},{"k":"type","s":"___ es nicht geregnet, wären wir gewandert. (haben, без wenn)","a":["Hätte"],"ru":"Если бы не было дождя, мы бы пошли в поход."},{"k":"type","s":"___ wurde viel diskutiert. (заполнитель Vorfeld)","a":["Es"],"ru":"Много дискутировали."},{"k":"type","s":"Ist das Wasser warm, ___ können wir schwimmen. (коррелят в главном предложении)","a":["so","dann"],"ru":"Если вода тёплая, мы можем поплавать."},{"k":"order","w":["sollte","es","regnen","bleiben","wir","zu","Hause"],"a":["Sollte es regnen bleiben wir zu Hause","Wir bleiben zu Hause sollte es regnen"],"ru":"Если пойдёт дождь, мы останемся дома."},{"k":"order","w":["ich","habe","mich","gefreut","über","deinen","Besuch"],"a":["Ich habe mich über deinen Besuch gefreut","Über deinen Besuch habe ich mich gefreut","Ich habe mich gefreut über deinen Besuch"],"ru":"Я обрадовался твоему визиту."},{"k":"tr","ru":"Если у Вас возникнут вопросы, позвоните нам. (без wenn)","a":["Sollten Sie Fragen haben, rufen Sie uns an","Sollten Sie Fragen haben, rufen Sie uns bitte an","Sollten Sie Fragen haben, so rufen Sie uns an","Sollten Sie Fragen haben, dann rufen Sie uns an","Sollten Sie Fragen haben, bitte rufen Sie uns an","Sollten Sie noch Fragen haben, rufen Sie uns an","Sollten Sie noch Fragen haben, rufen Sie uns bitte an","Sollten Sie noch Fragen haben, so rufen Sie uns an","Sollten Sie noch Fragen haben, dann rufen Sie uns an","Sollten Sie noch Fragen haben, bitte rufen Sie uns an","Sollten Fragen auftreten, rufen Sie uns an","Sollten Fragen auftreten, rufen Sie uns bitte an","Sollten Fragen auftreten, so rufen Sie uns an","Sollten Fragen auftreten, dann rufen Sie uns an","Sollten Fragen auftreten, bitte rufen Sie uns an","Sollten Fragen entstehen, rufen Sie uns an","Sollten Fragen entstehen, rufen Sie uns bitte an","Sollten Fragen entstehen, so rufen Sie uns an","Sollten Fragen entstehen, dann rufen Sie uns an","Sollten Fragen entstehen, bitte rufen Sie uns an"]},{"k":"tr","ru":"Будь я на твоём месте, я бы согласился. (без wenn)","a":["Wäre ich an deiner Stelle, würde ich zustimmen","Wäre ich an deiner Stelle, würde ich zusagen","Wäre ich an deiner Stelle, wäre ich einverstanden","Wäre ich an deiner Stelle, würde ich einwilligen","Wäre ich an deiner Stelle, stimmte ich zu","Wäre ich an deiner Stelle, würde ich ja sagen","Wäre ich du, würde ich zustimmen","Wäre ich du, würde ich zusagen","Wäre ich du, wäre ich einverstanden","Wäre ich du, würde ich einwilligen","Wäre ich du, stimmte ich zu","Wäre ich du, würde ich ja sagen"]}]}];
